static char *msort( char *list, char **next, int (*cmp)(const char*,const char*) ){
  unsigned long offset;
  char *ep;
  char *set[30];
  int i;
  offset = (unsigned long)((char*)next - (char*)list);
  for(i=0; i<30; i++) set[i] = 0;
  while( list ){
    ep = list;
    list = (*(char**)(((char*)list)+offset));
    (*(char**)(((char*)ep)+offset)) = 0;
    for(i=0; i<30 -1 && set[i]!=0; i++){
      ep = merge(set[i],ep,cmp,offset);
      set[i] = 0;
    }
    set[i] = merge(set[i],ep,cmp,offset);
  }
  ep = 0;
  for(i=0; i<30; i++) if( set[i] ) ep = merge(set[i],ep,cmp,offset);
  return ep;
}

