void OptPrint(void){
  int i;
  int max, len;
  max = 0;
  for(i=0; op[i].label; i++){
    len = ((int)strlen(op[i].label)) + 1;
    switch( op[i].type ){
      case OPT_FLAG: case OPT_FFLAG: break;
      case OPT_INT: case OPT_FINT: len += 9;
        break;
      case OPT_DBL: case OPT_FDBL: len += 6;
        break;
      case OPT_STR: case OPT_FSTR: len += 8;
        break;
    }
    if( len>max ) max = len;
  }
  for(i=0; op[i].label; i++){
    switch( op[i].type ){
      case OPT_FLAG: case OPT_FFLAG: fprintf(errstream,"  -%-*s  %s\n",max,op[i].label,op[i].message);
        break;
      case OPT_INT: case OPT_FINT: fprintf(errstream,"  -%s<integer>%*s  %s\n",op[i].label, (int)(max-((int)strlen(op[i].label))-9),"",op[i].message);
        break;
      case OPT_DBL: case OPT_FDBL: fprintf(errstream,"  -%s<real>%*s  %s\n",op[i].label, (int)(max-((int)strlen(op[i].label))-6),"",op[i].message);
        break;
      case OPT_STR: case OPT_FSTR: fprintf(errstream,"  -%s<string>%*s  %s\n",op[i].label, (int)(max-((int)strlen(op[i].label))-8),"",op[i].message);
        break;
    }
  }
}

void Parse(struct lemon *gp) {
  struct pstate ps;
  FILE *fp;
  char *filebuf;
  unsigned int filesize;
  int lineno;
  int c;
  char *cp, *nextcp;
  int startline = 0;
  memset(&ps, '\0', sizeof(ps));
  ps.gp = gp;
  ps.filename = gp->filename;
  ps.errorcnt = 0;
  ps.state = INITIALIZE;
  fp = fopen(ps.filename,"rb");
  if( fp==0 ){
    ErrorMsg(ps.filename,0,"Can't open this file for reading.");
    gp->errorcnt++;
    return;
  }
  fseek(fp,0,2);
  filesize = ftell(fp);
  rewind(fp);
  filebuf = (char *)lemon_malloc( filesize+1 );
  if( filesize>100000000 || filebuf==0 ){
    ErrorMsg(ps.filename,0,"Input file too large.");
    lemon_free(filebuf);
    gp->errorcnt++;
    fclose(fp);
    return;
  }
  if( fread(filebuf,1,filesize,fp)!=filesize ){
    ErrorMsg(ps.filename,0,"Can't read in all %d bytes of this file.", filesize);
    lemon_free(filebuf);
    gp->errorcnt++;
    fclose(fp);
    return;
  }
  fclose(fp);
  filebuf[filesize] = 0;
  preprocess_input(filebuf);
  if( gp->printPreprocessed ){
    printf("%s\n", filebuf);
    return;
  }
  lineno = 1;
  for(cp=filebuf; (c= *cp)!=0; ){
    if( c=='\n' ) lineno++;
    if( ((*__ctype_b_loc ())[(int) (((unsigned char)(c)))] & (unsigned short int) _ISspace) ){ cp++; continue; }
    if( c=='/' && cp[1]=='/' ){
      cp+=2;
      while( (c= *cp)!=0 && c!='\n' ) cp++;
      continue;
    }
    if( c=='/' && cp[1]=='*' ){
      cp+=2;
      if( (*cp)=='/' ) cp++;
      while( (c= *cp)!=0 && (c!='/' || cp[-1]!='*') ){
        if( c=='\n' ) lineno++;
        cp++;
      }
      if( c ) cp++;
      continue;
    }
    ps.tokenstart = cp;
    ps.tokenlineno = lineno;
    if( c=='\"' ){
      cp++;
      while( (c= *cp)!=0 && c!='\"' ){
        if( c=='\n' ) lineno++;
        cp++;
      }
      if( c==0 ){
        ErrorMsg(ps.filename,startline, "String starting on this line is not terminated before " "the end of the file.");
        ps.errorcnt++;
        nextcp = cp;
      }else{
        nextcp = cp+1;
      }
    }else if( c=='{' ){
      int level;
      cp++;
      for(level=1; (c= *cp)!=0 && (level>1 || c!='}'); cp++){
        if( c=='\n' ) lineno++;
        else if( c=='{' ) level++;
        else if( c=='}' ) level--;
        else if( c=='/' && cp[1]=='*' ){
          int prevc;
          cp = &cp[2];
          prevc = 0;
          while( (c= *cp)!=0 && (c!='/' || prevc!='*') ){
            if( c=='\n' ) lineno++;
            prevc = c;
            cp++;
          }
        }else if( c=='/' && cp[1]=='/' ){
          cp = &cp[2];
          while( (c= *cp)!=0 && c!='\n' ) cp++;
          if( c ) lineno++;
        }else if( c=='\'' || c=='\"' ){
          int startchar, prevc;
          startchar = c;
          prevc = 0;
          for(cp++; (c= *cp)!=0 && (c!=startchar || prevc=='\\'); cp++){
            if( c=='\n' ) lineno++;
            if( prevc=='\\' ) prevc = 0;
            else prevc = c;
          }
        }
      }
      if( c==0 ){
        ErrorMsg(ps.filename,ps.tokenlineno, "C code starting on this line is not terminated before " "the end of the file.");
        ps.errorcnt++;
        nextcp = cp;
      }else{
        nextcp = cp+1;
      }
    }else if( ((*__ctype_b_loc ())[(int) (((unsigned char)(c)))] & (unsigned short int) _ISalnum) ){
      while( (c= *cp)!=0 && (((*__ctype_b_loc ())[(int) (((unsigned char)(c)))] & (unsigned short int) _ISalnum) || c=='_') ) cp++;
      nextcp = cp;
    }else if( c==':' && cp[1]==':' && cp[2]=='=' ){
      cp += 3;
      nextcp = cp;
    }else if( (c=='/' || c=='|') && ((*__ctype_b_loc ())[(int) (((unsigned char)(cp[1])))] & (unsigned short int) _ISalpha) ){
      cp += 2;
      while( (c = *cp)!=0 && (((*__ctype_b_loc ())[(int) (((unsigned char)(c)))] & (unsigned short int) _ISalnum) || c=='_') ) cp++;
      nextcp = cp;
    }else{
      cp++;
      nextcp = cp;
    }
    c = *cp;
    *cp = 0;
    parseonetoken(&ps);
    *cp = (char)c;
    cp = nextcp;
  }
  lemon_free(filebuf);
  gp->rule = ps.firstrule;
  gp->errorcnt = ps.errorcnt;
}

struct plink *Plink_new(void){
  struct plink *newlink;
  if( plink_freelist==0 ){
    int i;
    int amt = 100;
    plink_freelist = (struct plink *)lemon_calloc( amt, sizeof(struct plink) );
    if( plink_freelist==0 ){
      fprintf(stderr, "Unable to allocate memory for a new follow-set propagation link.\n");
      exit(1);
    }
    for(i=0; i<amt-1; i++) plink_freelist[i].next = &plink_freelist[i+1];
    plink_freelist[amt-1].next = 0;
  }
  newlink = plink_freelist;
  plink_freelist = plink_freelist->next;
  return newlink;
}

void Plink_add(struct plink **plpp, struct config *cfp) {
  struct plink *newlink;
  newlink = Plink_new();
  newlink->next = *plpp;
  *plpp = newlink;
  newlink->cfp = cfp;
}

void Plink_copy(struct plink **to, struct plink *from) {
  struct plink *nextpl;
  while( from ){
    nextpl = from->next;
    from->next = *to;
    *to = from;
    from = nextpl;
  }
}

void Plink_delete(struct plink *plp) {
  struct plink *nextpl;
  while( plp ){
    nextpl = plp->next;
    plp->next = plink_freelist;
    plink_freelist = plp;
    plp = nextpl;
  }
}

