static char *merge( char *a, char *b, int (*cmp)(const char*,const char*), int offset ){
  char *ptr, *head;
  if( a==0 ){
    head = b;
  }else if( b==0 ){
    head = a;
  }else{
    if( (*cmp)(a,b)<=0 ){
      ptr = a;
      a = (*(char**)(((char*)a)+offset));
    }else{
      ptr = b;
      b = (*(char**)(((char*)b)+offset));
    }
    head = ptr;
    while( a && b ){
      if( (*cmp)(a,b)<=0 ){
        (*(char**)(((char*)ptr)+offset)) = a;
        ptr = a;
        a = (*(char**)(((char*)a)+offset));
      }else{
        (*(char**)(((char*)ptr)+offset)) = b;
        ptr = b;
        b = (*(char**)(((char*)b)+offset));
      }
    }
    if( a ) (*(char**)(((char*)ptr)+offset)) = a;
    else (*(char**)(((char*)ptr)+offset)) = b;
  }
  return head;
}

