}

int PrintAction( struct action *ap, FILE *fp, int indent ){
  int result = 1;
  switch( ap->type ){
    case SHIFT: {
      struct state *stp = ap->x.stp;
      fprintf(fp,"%*s shift        %-7d",indent,ap->sp->name,stp->statenum);
      break;
    }
    case REDUCE: {
      struct rule *rp = ap->x.rp;
      fprintf(fp,"%*s reduce       %-7d",indent,ap->sp->name,rp->iRule);
      RulePrint(fp, rp, -1);
      break;
    }
    case SHIFTREDUCE: {
      struct rule *rp = ap->x.rp;
      fprintf(fp,"%*s shift-reduce %-7d",indent,ap->sp->name,rp->iRule);
      RulePrint(fp, rp, -1);
      break;
    }
    case ACCEPT: fprintf(fp,"%*s accept",indent,ap->sp->name);
      break;
    case ERROR: fprintf(fp,"%*s error",indent,ap->sp->name);
      break;
    case SRCONFLICT: case RRCONFLICT: fprintf(fp,"%*s reduce       %-7d ** Parsing conflict **", indent,ap->sp->name,ap->x.rp->iRule);
      break;
    case SSCONFLICT: fprintf(fp,"%*s shift        %-7d ** Parsing conflict **", indent,ap->sp->name,ap->x.stp->statenum);
      break;
    case SH_RESOLVED: if( showPrecedenceConflict ){
        fprintf(fp,"%*s shift        %-7d -- dropped by precedence", indent,ap->sp->name,ap->x.stp->statenum);
      }else{
        result = 0;
      }
      break;
    case RD_RESOLVED: if( showPrecedenceConflict ){
        fprintf(fp,"%*s reduce %-7d -- dropped by precedence", indent,ap->sp->name,ap->x.rp->iRule);
      }else{
        result = 0;
      }
      break;
    case NOT_USED: result = 0;
      break;
  }
  if( result && ap->spOpt ){
    fprintf(fp,"  /* because %s==%s */", ap->sp->name, ap->spOpt->name);
  }
  return result;
}

        char *pathsearch(char *argv0, char *name, int modemask) {
  const char *pathlist;
  char *pathbufptr = 0;
  char *pathbuf = 0;
  char *path,*cp;
  char c;
  cp = strrchr(argv0,'/');
  if( cp ){
    c = *cp;
    *cp = 0;
    path = (char *)lemon_malloc( ((int)strlen(argv0)) + ((int)strlen(name)) + 2 );
    if( path ) lemon_sprintf(path,"%s/%s",argv0,name);
    *cp = c;
  }else{
    pathlist = getenv("PATH");
    if( pathlist==0 ) pathlist = ".:/bin:/usr/bin";
    pathbuf = (char *) lemon_malloc( ((int)strlen(pathlist)) + 1 );
    path = (char *)lemon_malloc( ((int)strlen(pathlist))+((int)strlen(name))+2 );
    if( (pathbuf != 0) && (path!=0) ){
      pathbufptr = pathbuf;
      lemon_strcpy(pathbuf, pathlist);
      while( *pathbuf ){
        cp = strchr(pathbuf,':');
        if( cp==0 ) cp = &pathbuf[((int)strlen(pathbuf))];
        c = *cp;
        *cp = 0;
        lemon_sprintf(path,"%s/%s",pathbuf,name);
        *cp = c;
        if( c==0 ) pathbuf[0] = 0;
        else pathbuf = &cp[1];
        if( access(path,modemask)==0 ) break;
      }
    }
    lemon_free(pathbufptr);
  }
  return path;
}

        int compute_action(struct lemon *lemp, struct action *ap) {
  int act;
  switch( ap->type ){
    case SHIFT: act = ap->x.stp->statenum; break;
    case SHIFTREDUCE: {
      if( ap->sp->index>=lemp->nterminal && (lemp->errsym==0 || ap->sp->index!=lemp->errsym->index) ){
        act = lemp->minReduce + ap->x.rp->iRule;
      }else{
        act = lemp->minShiftReduce + ap->x.rp->iRule;
      }
      break;
    }
    case REDUCE: act = lemp->minReduce + ap->x.rp->iRule; break;
    case ERROR: act = lemp->errAction; break;
    case ACCEPT: act = lemp->accAction; break;
    default: act = -1; break;
  }
  return act;
}

