int sqlite3_format_query_result( sqlite3_stmt *pStmt, const sqlite3_qrf_spec *pSpec, char **pzErr ){
  Qrf qrf;
  if( pStmt==0 ) return 0;
  if( pSpec==0 ) return 21;
  if( sqlite3_stmt_busy(pStmt) ) return 5;
  qrfInitialize(&qrf, pStmt, pSpec, pzErr);
  switch( qrf.spec.eStyle ){
    case 1: case 2: case 13: case 19: {
      qrfColumnar(&qrf);
      break;
    }
    case 6: {
      qrfExplain(&qrf);
      break;
    }
    case 18: {
      qrfScanStatusVm(&qrf);
      break;
    }
    case 16: case 17: {
      qrfEqpStats(&qrf);
      break;
    }
    default: {
      while( qrf.iErr==0 && sqlite3_step(pStmt)==100 ){
        qrfOneSimpleRow(&qrf);
      }
      if( qrf.nCol>0 && qrf.nRow==0 && qrf.spec.bTitles==3 ){
        qrfSimpleTitle(&qrf);
      }
      if( qrf.nCol>0 && qrf.spec.bRowCount==2 ){
        const char *zPlural = qrf.nRow==1 ? "" : "s";
        switch( qrf.spec.eStyle ){
          case 11: if( qrf.nRow>0 ) sqlite3_str_append(qrf.pOut, "\n", 1);
          case 4: case 12: case 15: sqlite3_str_appendf(qrf.pOut,"(%lld row%s)\n",qrf.nRow,zPlural);
            break;
          case 7: sqlite3_str_appendf(qrf.pOut,"<!-- %lld row%s -->\n", qrf.nRow, zPlural);
            break;
          case 8: sqlite3_str_appendf(qrf.pOut,"/* %lld row%s inserted */\n", qrf.nRow, zPlural);
            break;
        }
      }
      break;
    }
  }
  qrfResetStmt(&qrf);
  qrfFinalize(&qrf);
  return qrf.iErr;
}

int sqlite3_qrf_wcwidth(int c){
  int iFirst, iLast;
  if( c<0x300 ) return 1;
  iFirst = 0;
  iLast = sizeof(aQrfUWidth)/sizeof(aQrfUWidth[0]) - 1;
  while( iFirst<iLast-1 ){
    int iMid = (iFirst+iLast)/2;
    int cMid = aQrfUWidth[iMid].iFirst;
    if( cMid < c ){
      iFirst = iMid;
    }else if( cMid > c ){
      iLast = iMid - 1;
    }else{
      return aQrfUWidth[iMid].w;
    }
  }
  if( aQrfUWidth[iLast].iFirst > c ) return aQrfUWidth[iFirst].w;
  return aQrfUWidth[iLast].w;
}

