          sqlite3_str_appendchar(pOut, nBlob, ' ');
          sqlite3_str_appendchar(pOut, nBlob, ' ');
          if( p->spec.eBlob==2 ){
            sqlite3_str_appendchar(pOut, 1, '\'');
