static void qrfScanStatusVm(Qrf *p){
  sqlite3_stmt *pOrigStmt = p->pStmt;
  sqlite3_stmt *pExplain;
  int rc;
  static const char *zSql = "  SELECT addr, opcode, p1, p2, p3, p4, p5, comment, nexec," "   format('% 6s (%.2f%%)'," "      CASE WHEN ncycle<100_000 THEN ncycle || ' '" "         WHEN ncycle<100_000_000 THEN (ncycle/1_000) || 'K'" "         WHEN ncycle<100_000_000_000 THEN (ncycle/1_000_000) || 'M'" "         ELSE (ncycle/1000_000_000) || 'G' END," "       ncycle*100.0/(sum(ncycle) OVER ())" "   )  AS cycles" "   FROM bytecode(?1)";
  rc = sqlite3_prepare_v2(p->db, zSql, -1, &pExplain, 0);
  if( rc ){
    qrfError(p, rc, "%s", sqlite3_errmsg(p->db));
    sqlite3_finalize(pExplain);
    return;
  }
  sqlite3_bind_pointer(pExplain, 1, pOrigStmt, "stmt-pointer", 0);
  p->pStmt = pExplain;
  p->nCol = 10;
  qrfExplain(p);
  sqlite3_finalize(pExplain);
  p->pStmt = pOrigStmt;
}

