      goto qrf_reinit;
    }
    case 12: {
      if( p->spec.zColumnSep==0 ) p->spec.zColumnSep = "|";
      if( p->spec.zRowSep==0 ) p->spec.zRowSep = "\n";
      break;
    }
    case 10: case 9: {
      p->spec.eText = 6;
      p->spec.zNull = "null";
