static const char *sqlite3re_compile( ReCompiled **ppRe, const char *zIn, int mxRe, int noCase ){
  ReCompiled *pRe;
  const char *zErr;
  int i, j;
  *ppRe = 0;
  pRe = sqlite3_malloc64( sizeof(*pRe) );
  if( pRe==0 ){
