static int zipfileReadData( FILE *pFile, u8 *aRead, i64 nRead, i64 iOff, char **pzErrmsg ){
  size_t n;
  fseek(pFile, (long)iOff, 0);
  n = fread(aRead, 1, (long)nRead, pFile);
  if( n!=(size_t)nRead ){
    sqlite3_free(*pzErrmsg);
    *pzErrmsg = sqlite3_mprintf("error in fread()");
    return 1;
  }
  return 0;
}

static int zipfileAppendData( ZipfileTab *pTab, const u8 *aWrite, int nWrite ){
  if( nWrite>0 ){
    size_t n = nWrite;
    fseek(pTab->pWriteFd, (long)pTab->szCurrent, 0);
    n = fwrite(aWrite, 1, nWrite, pTab->pWriteFd);
    if( (int)n!=nWrite ){
      zipfileTableErr(pTab,"error in fwrite()");
      return 1;
    }
    pTab->szCurrent += nWrite;
  }
  return 0;
}

static u16 zipfileGetU16(const u8 *aBuf){
  return (aBuf[1] << 8) + aBuf[0];
}

static u32 zipfileGetU32(const u8 *aBuf){
  if( aBuf==0 ) return 0;
  return ((u32)(aBuf[3]) << 24) + ((u32)(aBuf[2]) << 16) + ((u32)(aBuf[1]) << 8) + ((u32)(aBuf[0]) << 0);
}

static void zipfilePutU16(u8 *aBuf, u16 val){
  aBuf[0] = val & 0xFF;
  aBuf[1] = (val>>8) & 0xFF;
}

static void zipfilePutU32(u8 *aBuf, u32 val){
  aBuf[0] = val & 0xFF;
  aBuf[1] = (val>>8) & 0xFF;
  aBuf[2] = (val>>16) & 0xFF;
  aBuf[3] = (val>>24) & 0xFF;
}

static int zipfileReadCDS(u8 *aBuf, ZipfileCDS *pCDS){
  u8 *aRead = aBuf;
  u32 sig = ( aRead+=4, zipfileGetU32(aRead-4) );
  int rc = 0;
  if( sig!=0x02014b50 ){
    rc = 1;
  }else{
    pCDS->iVersionMadeBy = ( aRead+=2, zipfileGetU16(aRead-2) );
    pCDS->iVersionExtract = ( aRead+=2, zipfileGetU16(aRead-2) );
    pCDS->flags = ( aRead+=2, zipfileGetU16(aRead-2) );
    pCDS->iCompression = ( aRead+=2, zipfileGetU16(aRead-2) );
    pCDS->mTime = ( aRead+=2, zipfileGetU16(aRead-2) );
    pCDS->mDate = ( aRead+=2, zipfileGetU16(aRead-2) );
    pCDS->crc32 = ( aRead+=4, zipfileGetU32(aRead-4) );
    pCDS->szCompressed = ( aRead+=4, zipfileGetU32(aRead-4) );
    pCDS->szUncompressed = ( aRead+=4, zipfileGetU32(aRead-4) );
    ((void) (0));
    pCDS->nFile = ( aRead+=2, zipfileGetU16(aRead-2) );
    pCDS->nExtra = ( aRead+=2, zipfileGetU16(aRead-2) );
    pCDS->nComment = ( aRead+=2, zipfileGetU16(aRead-2) );
    pCDS->iDiskStart = ( aRead+=2, zipfileGetU16(aRead-2) );
    pCDS->iInternalAttr = ( aRead+=2, zipfileGetU16(aRead-2) );
    pCDS->iExternalAttr = ( aRead+=4, zipfileGetU32(aRead-4) );
    pCDS->iOffset = ( aRead+=4, zipfileGetU32(aRead-4) );
    ((void) (0));
  }
  return rc;
}

static int zipfileReadLFH( u8 *aBuffer, ZipfileLFH *pLFH ){
  u8 *aRead = aBuffer;
  int rc = 0;
  u32 sig = ( aRead+=4, zipfileGetU32(aRead-4) );
  if( sig!=0x04034b50 ){
    rc = 1;
  }else{
    pLFH->iVersionExtract = ( aRead+=2, zipfileGetU16(aRead-2) );
    pLFH->flags = ( aRead+=2, zipfileGetU16(aRead-2) );
    pLFH->iCompression = ( aRead+=2, zipfileGetU16(aRead-2) );
    pLFH->mTime = ( aRead+=2, zipfileGetU16(aRead-2) );
    pLFH->mDate = ( aRead+=2, zipfileGetU16(aRead-2) );
    pLFH->crc32 = ( aRead+=4, zipfileGetU32(aRead-4) );
    pLFH->szCompressed = ( aRead+=4, zipfileGetU32(aRead-4) );
    pLFH->szUncompressed = ( aRead+=4, zipfileGetU32(aRead-4) );
    pLFH->nFile = ( aRead+=2, zipfileGetU16(aRead-2) );
    pLFH->nExtra = ( aRead+=2, zipfileGetU16(aRead-2) );
    if( pLFH->nFile>(250) ) rc = 1;
  }
  return rc;
}

static int zipfileScanExtra(u8 *aExtra, int nExtra, u32 *pmTime){
  int ret = 0;
  u8 *p = aExtra;
  u8 *pEnd = &aExtra[nExtra];
  while( p+(2*sizeof(u16) + 1 + sizeof(u32))<=pEnd ){
    u16 id = ( p+=2, zipfileGetU16(p-2) );
    u16 nByte = ( p+=2, zipfileGetU16(p-2) );
    switch( id ){
      case 0x5455: {
        u8 b = p[0];
        if( b & 0x01 ){
          *pmTime = zipfileGetU32(&p[1]);
          ret = 1;
        }
        break;
      }
    }
    p += nByte;
  }
  return ret;
}

static u32 zipfileMtime(ZipfileCDS *pCDS){
  int Y,M,D,X1,X2,A,B,sec,min,hr;
  i64 JDsec;
  Y = (1980 + ((pCDS->mDate >> 9) & 0x7F));
  M = ((pCDS->mDate >> 5) & 0x0F);
  D = (pCDS->mDate & 0x1F);
  sec = (pCDS->mTime & 0x1F)*2;
  min = (pCDS->mTime >> 5) & 0x3F;
  hr = (pCDS->mTime >> 11) & 0x1F;
  if( M<=2 ){
    Y--;
    M += 12;
  }
  X1 = 36525*(Y+4716)/100;
  X2 = 306001*(M+1)/10000;
  A = Y/100;
  B = 2 - A + (A/4);
  JDsec = (i64)((X1 + X2 + D + B - 1524.5)*86400) + hr*3600 + min*60 + sec;
  return (u32)(JDsec - (i64)24405875*(i64)8640);
}

static void zipfileMtimeToDos(ZipfileCDS *pCds, u32 mUnixTime){
  i64 JD = (i64)2440588 + mUnixTime / (24*60*60);
  int A, B, C, D, E;
  int yr, mon, day;
  int hr, min, sec;
  A = (int)((JD - 1867216.25)/36524.25);
  A = (int)(JD + 1 + A - (A/4));
  B = A + 1524;
  C = (int)((B - 122.1)/365.25);
  D = (36525*(C&32767))/100;
  E = (int)((B-D)/30.6001);
  day = B - D - (int)(30.6001*E);
  mon = (E<14 ? E-1 : E-13);
  yr = mon>2 ? C-4716 : C-4715;
  hr = (mUnixTime % (24*60*60)) / (60*60);
  min = (mUnixTime % (60*60)) / 60;
  sec = (mUnixTime % 60);
  if( yr>=1980 ){
    pCds->mDate = (u16)(day + (mon << 5) + ((yr-1980) << 9));
    pCds->mTime = (u16)(sec/2 + (min<<5) + (hr<<11));
  }else{
    pCds->mDate = pCds->mTime = 0;
  }
  ((void) (0));
}

static int zipfileCorrupt(char **pzErr){
  sqlite3_free(*pzErr);
  *pzErr = sqlite3_mprintf("zip archive is corrupt");
  return 11;
}

static int zipfileGetEntry( ZipfileTab *pTab, const u8 *aBlob, i64 nBlob, FILE *pFile, i64 iOff, ZipfileEntry **ppEntry ){
  u8 *aRead;
  char **pzErr = &pTab->base.zErrMsg;
  int rc = 0;
  if( aBlob==0 ){
    aRead = pTab->aBuffer;
    rc = zipfileReadData(pFile, aRead, 46, iOff, pzErr);
  }else{
    if( (iOff+46)>nBlob ){
      return zipfileCorrupt(pzErr);
    }
    aRead = (u8*)&aBlob[iOff];
  }
  if( rc==0 ){
    sqlite3_int64 nAlloc;
    ZipfileEntry *pNew;
    int nFile = zipfileGetU16(&aRead[28]);
    int nExtra = zipfileGetU16(&aRead[28 +2]);
    nExtra += zipfileGetU16(&aRead[28 +4]);
    nAlloc = sizeof(ZipfileEntry) + nExtra;
    if( aBlob ){
      nAlloc += zipfileGetU32(&aRead[20]);
    }
    pNew = (ZipfileEntry*)sqlite3_malloc64(nAlloc);
    if( pNew==0 ){
      rc = 7;
    }else{
      memset(pNew, 0, sizeof(ZipfileEntry));
      rc = zipfileReadCDS(aRead, &pNew->cds);
      if( rc!=0 ){
        zipfileTableErr(pTab, "failed to read CDS at offset %lld", iOff);
      }else if( aBlob==0 ){
        rc = zipfileReadData( pFile, aRead, nExtra+nFile, iOff+46, pzErr );
      }else{
        aRead = (u8*)&aBlob[iOff + 46];
        if( (iOff + 46 + nFile + nExtra)>nBlob ){
          rc = zipfileCorrupt(pzErr);
        }
      }
    }
    if( rc==0 ){
      u32 *pt = &pNew->mUnixTime;
      pNew->cds.zFile = sqlite3_malloc64(nFile+1);
      if( pNew->cds.zFile!=0 ){
        memcpy(pNew->cds.zFile, aRead, nFile);
        pNew->cds.zFile[nFile] = 0;
      }
      pNew->aExtra = (u8*)&pNew[1];
      memcpy(pNew->aExtra, &aRead[nFile], nExtra);
      if( pNew->cds.zFile==0 ){
        rc = 7;
      }else if( 0==zipfileScanExtra(&aRead[nFile], pNew->cds.nExtra, pt) ){
        pNew->mUnixTime = zipfileMtime(&pNew->cds);
      }
    }
    if( rc==0 ){
      static const int szFix = 30;
      ZipfileLFH lfh;
      if( pFile ){
        rc = zipfileReadData(pFile, aRead, szFix, pNew->cds.iOffset, pzErr);
      }else{
        aRead = (u8*)&aBlob[pNew->cds.iOffset];
        if( ((i64)pNew->cds.iOffset + 30)>nBlob ){
          rc = zipfileCorrupt(pzErr);
        }
      }
      memset(&lfh, 0, sizeof(lfh));
      if( rc==0 ) rc = zipfileReadLFH(aRead, &lfh);
      if( rc==0 ){
        pNew->iDataOff = (i64)pNew->cds.iOffset + 30;
        pNew->iDataOff += lfh.nFile + lfh.nExtra;
        if( aBlob && pNew->cds.szCompressed ){
          if( pNew->iDataOff + pNew->cds.szCompressed > nBlob ){
            rc = zipfileCorrupt(pzErr);
          }else{
            pNew->aData = &pNew->aExtra[nExtra];
            memcpy(pNew->aData, &aBlob[pNew->iDataOff], pNew->cds.szCompressed);
          }
        }
      }else{
        zipfileTableErr(pTab, "failed to read LFH at offset %d", (int)pNew->cds.iOffset );
      }
    }
    if( rc!=0 ){
      zipfileEntryFree(pNew);
    }else{
      *ppEntry = pNew;
    }
  }
  return rc;
}

static int zipfileNext(sqlite3_vtab_cursor *cur){
  ZipfileCsr *pCsr = (ZipfileCsr*)cur;
  int rc = 0;
  if( pCsr->pFile ){
    i64 iEof = (i64)pCsr->eocd.iOffset + (i64)pCsr->eocd.nSize;
    zipfileEntryFree(pCsr->pCurrent);
    pCsr->pCurrent = 0;
    if( pCsr->iNextOff>=iEof ){
      pCsr->bEof = 1;
    }else{
      ZipfileEntry *p = 0;
      ZipfileTab *pTab = (ZipfileTab*)(cur->pVtab);
      rc = zipfileGetEntry(pTab, 0, 0, pCsr->pFile, pCsr->iNextOff, &p);
      if( rc==0 ){
        pCsr->iNextOff += 46;
        pCsr->iNextOff += (int)p->cds.nExtra + p->cds.nFile + p->cds.nComment;
      }
      pCsr->pCurrent = p;
    }
  }else{
    if( !pCsr->bNoop ){
      pCsr->pCurrent = pCsr->pCurrent->pNext;
    }
    if( pCsr->pCurrent==0 ){
      pCsr->bEof = 1;
    }
  }
  pCsr->bNoop = 0;
  return rc;
}

static void zipfileFree(void *p) {
  sqlite3_free(p);
}

static void zipfileInflate( sqlite3_context *pCtx, const u8 *aIn, int nIn, int nOut ){
  u8 *aRes = sqlite3_malloc64(nOut);
  if( aRes==0 ){
    sqlite3_result_error_nomem(pCtx);
  }else{
    int err;
    z_stream str;
    memset(&str, 0, sizeof(str));
    str.next_in = (Byte*)aIn;
    str.avail_in = nIn;
    str.next_out = (Byte*)aRes;
    str.avail_out = nOut;
    err = inflateInit2_((&str), (-15), "1.3", (int)sizeof(z_stream));
    if( err!=0 ){
      zipfileCtxErrorMsg(pCtx, "inflateInit2() failed (%d)", err);
    }else{
      err = inflate(&str, 0);
      if( err!=1 ){
        zipfileCtxErrorMsg(pCtx, "inflate() failed (%d)", err);
      }else{
        sqlite3_result_blob(pCtx, aRes, (int)str.total_out, zipfileFree);
        aRes = 0;
      }
    }
    sqlite3_free(aRes);
    inflateEnd(&str);
  }
}

static int zipfileDeflate( const u8 *aIn, int nIn, u8 **ppOut, int *pnOut, char **pzErr ){
  int rc = 0;
  sqlite3_int64 nAlloc;
  z_stream str;
  u8 *aOut;
  memset(&str, 0, sizeof(str));
  str.next_in = (Bytef*)aIn;
  str.avail_in = nIn;
  deflateInit2_((&str),(9),(8),(-15),(8), (0), "1.3", (int)sizeof(z_stream));
  nAlloc = deflateBound(&str, nIn);
  aOut = (u8*)sqlite3_malloc64(nAlloc);
  if( aOut==0 ){
    rc = 7;
  }else{
    int res;
    str.next_out = aOut;
    str.avail_out = nAlloc;
    res = deflate(&str, 4);
    if( res==1 ){
      *ppOut = aOut;
      *pnOut = (int)str.total_out;
    }else{
      sqlite3_free(aOut);
      *pzErr = sqlite3_mprintf("zipfile: deflate() error");
      rc = 1;
    }
    deflateEnd(&str);
  }
  return rc;
}

static int zipfileColumn( sqlite3_vtab_cursor *cur, sqlite3_context *ctx, int i ){
  ZipfileCsr *pCsr = (ZipfileCsr*)cur;
  ZipfileCDS *pCDS = &pCsr->pCurrent->cds;
  int rc = 0;
  switch( i ){
    case 0: sqlite3_result_text(ctx, pCDS->zFile, -1, ((sqlite3_destructor_type)-1));
      break;
    case 1: sqlite3_result_int(ctx, pCDS->iExternalAttr >> 16);
      break;
    case 2: {
      sqlite3_result_int64(ctx, pCsr->pCurrent->mUnixTime);
      break;
    }
    case 3: {
      if( sqlite3_vtab_nochange(ctx)==0 ){
        sqlite3_result_int64(ctx, pCDS->szUncompressed);
      }
      break;
    }
    case 4: if( sqlite3_vtab_nochange(ctx) ) break;
    case 5: {
      if( i==4 || pCDS->iCompression==0 || pCDS->iCompression==8 ){
        int sz = pCDS->szCompressed;
        int szFinal = pCDS->szUncompressed;
        if( szFinal>0 ){
          u8 *aBuf;
          u8 *aFree = 0;
          if( pCsr->pCurrent->aData ){
            aBuf = pCsr->pCurrent->aData;
          }else{
            aBuf = aFree = sqlite3_malloc64(sz);
            if( aBuf==0 ){
              rc = 7;
            }else{
              FILE *pFile = pCsr->pFile;
              if( pFile==0 ){
                pFile = ((ZipfileTab*)(pCsr->base.pVtab))->pWriteFd;
              }
              rc = zipfileReadData(pFile, aBuf, sz, pCsr->pCurrent->iDataOff, &pCsr->base.pVtab->zErrMsg );
            }
          }
          if( rc==0 ){
            if( i==5 && pCDS->iCompression ){
              zipfileInflate(ctx, aBuf, sz, szFinal);
            }else{
              sqlite3_result_blob(ctx, aBuf, sz, ((sqlite3_destructor_type)-1));
            }
          }
