static void stmtrandFunc( sqlite3_context *context, int argc, sqlite3_value **argv ){
  Stmtrand *p;
  p = (Stmtrand*)sqlite3_get_auxdata(context, (-4418371));
  if( p==0 ){
    unsigned int seed;
    p = sqlite3_malloc64( sizeof(*p) );
    if( p==0 ){
      sqlite3_result_error_nomem(context);
      return;
    }
    if( argc>=1 ){
      seed = (unsigned int)sqlite3_value_int(argv[0]);
    }else{
      seed = 0;
    }
    p->x = seed | 1;
    p->y = seed;
    sqlite3_set_auxdata(context, (-4418371), p, sqlite3_free);
    p = (Stmtrand*)sqlite3_get_auxdata(context, (-4418371));
    if( p==0 ){
      sqlite3_result_error_nomem(context);
      return;
    }
  }
  p->x = (p->x>>1) ^ ((1+~(p->x&1)) & 0xd0000001);
  p->y = p->y*1103515245 + 12345;
  sqlite3_result_int(context, (int)((p->x ^ p->y)&0x7fffffff));
}

int sqlite3_stmtrand_init( sqlite3 *db, char **pzErrMsg, const sqlite3_api_routines *pApi ){
  int rc = 0;
  (void)(pApi);
  (void)pzErrMsg;
  rc = sqlite3_create_function(db, "stmtrand", 1, 1, 0, stmtrandFunc, 0, 0);
  if( rc==0 ){
    rc = sqlite3_create_function(db, "stmtrand", 0, 1, 0, stmtrandFunc, 0, 0);
  }
  return rc;
}

