  if( flags & 1 ) strappend(zLck, &i, "|UNLOCK");
  if( flags & 2 ) strappend(zLck, &i, "|LOCK");
  if( flags & 4 ) strappend(zLck, &i, "|SHARED");
  if( flags & 8 ) strappend(zLck, &i, "|EXCLUSIVE");
  if( flags & ~(0xf) ){
     sqlite3_snprintf(sizeof(zLck)-i, &zLck[i], "|0x%x", flags);
  }
  if( ofst>=0 && ofst<(int)(sizeof(azLockName)/sizeof(azLockName[0])) ){
    vfstrace_printf(pInfo, "%s.xShmLock(%s,ofst=%d(%s),n=%d,%s)", pInfo->zVfsName, p->zFName, ofst, azLockName[ofst], n, &zLck[1]);
  }else{
    vfstrace_printf(pInfo, "%s.xShmLock(%s,ofst=5d,n=%d,%s)", pInfo->zVfsName, p->zFName, ofst, n, &zLck[1]);
  }
  rc = p->pReal->pMethods->xShmLock(p->pReal, ofst, n, flags);
  vfstrace_print_errcode(pInfo, " -> %s\n", rc);
  return rc;
