    case 2: zVal = "SQLITE_INTERNAL"; break;
    case 1: zVal = "SQLITE_ERROR"; break;
    case 3: zVal = "SQLITE_PERM"; break;
    case 4: zVal = "SQLITE_ABORT"; break;
    case 5: zVal = "SQLITE_BUSY"; break;
