int vfstrace_register( const char *zTraceName, const char *zOldVfsName, int (*xOut)(const char*,void*), void *pOutArg, int makeDefault ){
  sqlite3_vfs *pNew;
  sqlite3_vfs *pRoot;
  vfstrace_info *pInfo;
  size_t nName;
  size_t nByte;
  pRoot = sqlite3_vfs_find(zOldVfsName);
  if( pRoot==0 ) return 12;
  nName = strlen(zTraceName);
  nByte = sizeof(*pNew) + sizeof(*pInfo) + nName + 1;
  pNew = sqlite3_malloc64( nByte );
  if( pNew==0 ) return 7;
  memset(pNew, 0, nByte);
  pInfo = (vfstrace_info*)&pNew[1];
  pNew->iVersion = pRoot->iVersion;
  pNew->szOsFile = pRoot->szOsFile + sizeof(vfstrace_file);
  pNew->mxPathname = pRoot->mxPathname;
  pNew->zName = (char*)&pInfo[1];
  memcpy((char*)&pInfo[1], zTraceName, nName+1);
  pNew->pAppData = pInfo;
  pNew->xOpen = vfstraceOpen;
  pNew->xDelete = vfstraceDelete;
  pNew->xAccess = vfstraceAccess;
  pNew->xFullPathname = vfstraceFullPathname;
  pNew->xDlOpen = pRoot->xDlOpen==0 ? 0 : vfstraceDlOpen;
  pNew->xDlError = pRoot->xDlError==0 ? 0 : vfstraceDlError;
  pNew->xDlSym = pRoot->xDlSym==0 ? 0 : vfstraceDlSym;
  pNew->xDlClose = pRoot->xDlClose==0 ? 0 : vfstraceDlClose;
  pNew->xRandomness = vfstraceRandomness;
  pNew->xSleep = vfstraceSleep;
  pNew->xCurrentTime = vfstraceCurrentTime;
  pNew->xGetLastError = pRoot->xGetLastError==0 ? 0 : vfstraceGetLastError;
  if( pNew->iVersion>=2 ){
    pNew->xCurrentTimeInt64 = pRoot->xCurrentTimeInt64==0 ? 0 : vfstraceCurrentTimeInt64;
    if( pNew->iVersion>=3 ){
      pNew->xSetSystemCall = pRoot->xSetSystemCall==0 ? 0 : vfstraceSetSystemCall;
      pNew->xGetSystemCall = pRoot->xGetSystemCall==0 ? 0 : vfstraceGetSystemCall;
      pNew->xNextSystemCall = pRoot->xNextSystemCall==0 ? 0 : vfstraceNextSystemCall;
    }
  }
  pInfo->pRootVfs = pRoot;
  pInfo->xOut = xOut;
  pInfo->pOutArg = pOutArg;
  pInfo->zVfsName = pNew->zName;
  pInfo->pTraceVfs = pNew;
  pInfo->mTrace = 0xffffffff;
  pInfo->bOn = 1;
  vfstrace_printf(pInfo, "%s.enabled_for(\"%s\")\n", pInfo->zVfsName, pRoot->zName);
  return sqlite3_vfs_register(pNew, makeDefault);
}

void vfstrace_unregister(const char *zTraceName){
  sqlite3_vfs *pVfs = sqlite3_vfs_find(zTraceName);
  if( pVfs==0 ) return;
  if( pVfs->xOpen!=vfstraceOpen ) return;
  sqlite3_vfs_unregister(pVfs);
  sqlite3_free(pVfs);
}

static void diskusedReset(DiskUsed *p){
  if( p->zSU ){
    char *zSql = sqlite3_mprintf("DROP TABLE temp.%s;", p->zSU);
    if( zSql ){
      sqlite3_exec(p->db, zSql, 0, 0, 0);
      sqlite3_free(zSql);
    }
  }
  sqlite3_str_free(p->pOut);
  sqlite3_free(p->zSU);
  memset(p, 0, sizeof(*p));
}

static void diskusedError(DiskUsed *p, const char *zFormat, ...){
  char *zErr;
  if( zFormat ){
    va_list ap;
    __builtin_va_start(ap, zFormat);
    zErr = sqlite3_vmprintf(zFormat, ap);
    __builtin_va_end(ap);
  }else{
    zErr = 0;
  }
  if( zErr==0 ){
    sqlite3_result_error_nomem(p->context);
  }else{
    sqlite3_result_error(p->context, zErr, -1);
    sqlite3_free(zErr);
  }
  diskusedReset(p);
}

static sqlite3_stmt *diskusedVPrep(DiskUsed *p, const char *zFmt, va_list ap){
  char *zSql;
  int rc;
  sqlite3_stmt *pStmt = 0;
  zSql = sqlite3_vmprintf(zFmt, ap);
  if( zSql==0 ){ diskusedError(p,0); return 0; }
  rc = sqlite3_prepare_v2(p->db, zSql, -1, &pStmt, 0);
  if( rc ){
    diskusedError(p, "SQL parse error: %s\nOriginal SQL: %s", sqlite3_errmsg(p->db), zSql);
    sqlite3_finalize(pStmt);
    diskusedReset(p);
    pStmt = 0;
  }
  sqlite3_free(zSql);
  return pStmt;
}

static sqlite3_stmt *diskusedPrepare(DiskUsed *p, const char *zFormat, ...){
  va_list ap;
  sqlite3_stmt *pStmt = 0;
  __builtin_va_start(ap, zFormat);
  pStmt = diskusedVPrep(p,zFormat,ap);
  __builtin_va_end(ap);
  return pStmt;
}

static int diskusedStmtFinish(DiskUsed *p, int rc, sqlite3_stmt *pStmt){
  if( rc==101 ){
    rc = 0;
  }
  if( rc!=0 || (rc = sqlite3_reset(pStmt))!=0 ){
    diskusedError(p, "SQL run-time error: %s\nOriginal SQL: %s", sqlite3_errmsg(p->db), sqlite3_sql(pStmt));
    diskusedReset(p);
  }
  sqlite3_finalize(pStmt);
  return rc;
}

static int diskusedSql(DiskUsed *p, const char *zFormat, ...){
  va_list ap;
  int rc;
  sqlite3_stmt *pStmt = 0;
  __builtin_va_start(ap, zFormat);
  pStmt = diskusedVPrep(p,zFormat,ap);
  __builtin_va_end(ap);
  if( pStmt==0 ) return 1;
  while( (rc = sqlite3_step(pStmt))==100 ){}
  if( rc==101 ){
    rc = 0;
  }else{
    diskusedError(p, "SQL run-time error: %s\nOriginal SQL: %s", sqlite3_errmsg(p->db), sqlite3_sql(pStmt));
    diskusedReset(p);
  }
  sqlite3_finalize(pStmt);
  return rc;
}

