static int display_stats( sqlite3 *db, ShellState *pArg, int bReset ){
  int iCur, iHiwtr;
  sqlite3_int64 iCur64, iHiwtr64;
  FILE *out;
  if( pArg==0 || pArg->out==0 ) return 0;
  out = pArg->out;
  if( pArg->pStmt && pArg->statsOn==2 ){
    int nCol, i, x;
