      iCur = sqlite3_stmt_status(pArg->pStmt, 4,bReset);
      cli_printf(out, "VM-steps: %d\n", iCur);
    }
    return 0;
  }
  displayStatLine(out, "Memory Used:", "%lld (max %lld) bytes", 0, bReset);
  displayStatLine(out, "Number of Outstanding Allocations:", "%lld (max %lld)", 9, bReset);
  if( pArg->shellFlgs & 0x00000001 ){
    displayStatLine(out, "Number of Pcache Pages Used:", "%lld (max %lld) pages", 1, bReset);
  }
  displayStatLine(out, "Number of Pcache Overflow Bytes:", "%lld (max %lld) bytes", 2, bReset);
  displayStatLine(out, "Largest Allocation:", "%lld bytes", 5, bReset);
  displayStatLine(out, "Largest Pcache Allocation:", "%lld bytes", 7, bReset);
  if( db ){
    if( pArg->shellFlgs & 0x00000002 ){
      iHiwtr = iCur = -1;
      sqlite3_db_status(db, 0, &iCur, &iHiwtr, bReset);
      cli_printf(out, "Lookaside Slots Used:                %d (max %d)\n", iCur, iHiwtr);
      sqlite3_db_status(db, 4, &iCur, &iHiwtr, bReset);
      cli_printf(out, "Successful lookaside attempts:       %d\n", iHiwtr);
      sqlite3_db_status(db, 5, &iCur, &iHiwtr, bReset);
      cli_printf(out, "Lookaside failures due to size:      %d\n", iHiwtr);
      sqlite3_db_status(db, 6, &iCur, &iHiwtr, bReset);
      cli_printf(out, "Lookaside failures due to OOM:       %d\n", iHiwtr);
    }
    iHiwtr = iCur = -1;
    sqlite3_db_status(db, 1, &iCur, &iHiwtr, bReset);
    cli_printf(out, "Pager Heap Usage:                    %d bytes\n", iCur);
    iHiwtr = iCur = -1;
    sqlite3_db_status(db, 7, &iCur, &iHiwtr, 1);
    cli_printf(out, "Page cache hits:                     %d\n", iCur);
    iHiwtr = iCur = -1;
    sqlite3_db_status(db, 8, &iCur, &iHiwtr, 1);
    cli_printf(out, "Page cache misses:                   %d\n", iCur);
    iHiwtr64 = iCur64 = -1;
    sqlite3_db_status64(db, 13, &iCur64, &iHiwtr64, 0);
    iHiwtr = iCur = -1;
    sqlite3_db_status(db, 9, &iCur, &iHiwtr, 1);
    cli_printf(out, "Page cache writes:                   %d\n", iCur);
    iHiwtr = iCur = -1;
    sqlite3_db_status(db, 12, &iCur, &iHiwtr, 1);
    cli_printf(out, "Page cache spills:                   %d\n", iCur);
    cli_printf(out, "Temporary data spilled to disk:      %lld\n", iCur64);
    sqlite3_db_status64(db, 13, &iCur64, &iHiwtr64, 1);
    iHiwtr = iCur = -1;
    sqlite3_db_status(db, 2, &iCur, &iHiwtr, bReset);
    cli_printf(out, "Schema Heap Usage:                   %d bytes\n", iCur);
    iHiwtr = iCur = -1;
    sqlite3_db_status(db, 3, &iCur, &iHiwtr, bReset);
    cli_printf(out, "Statement Heap/Lookaside Usage:      %d bytes\n", iCur);
  }
  if( pArg->pStmt ){
    int iHit, iMiss;
    iCur = sqlite3_stmt_status(pArg->pStmt, 1, bReset);
    cli_printf(out, "Fullscan Steps:                      %d\n", iCur);
    iCur = sqlite3_stmt_status(pArg->pStmt, 2, bReset);
    cli_printf(out, "Sort Operations:                     %d\n", iCur);
    iCur = sqlite3_stmt_status(pArg->pStmt, 3,bReset);
    cli_printf(out, "Autoindex Inserts:                   %d\n", iCur);
    iHit = sqlite3_stmt_status(pArg->pStmt, 8, bReset);
    iMiss = sqlite3_stmt_status(pArg->pStmt, 7, bReset);
    if( iHit || iMiss ){
      cli_printf(out, "Bloom filter bypass taken:           %d/%d\n", iHit, iHit+iMiss);
    }
    iCur = sqlite3_stmt_status(pArg->pStmt, 4, bReset);
    cli_printf(out, "Virtual Machine Steps:               %d\n", iCur);
    iCur = sqlite3_stmt_status(pArg->pStmt, 5,bReset);
    cli_printf(out, "Reprepare operations:                %d\n", iCur);
    iCur = sqlite3_stmt_status(pArg->pStmt, 6, bReset);
    cli_printf(out, "Number of times run:                 %d\n", iCur);
    iCur = sqlite3_stmt_status(pArg->pStmt, 99, bReset);
    cli_printf(out, "Memory used by prepared stmt:        %d\n", iCur);
  }
  displayLinuxIoStats(pArg->out);
  return 0;
}

