static int shell_exec( ShellState *pArg, const char *zSql, char **pzErrMsg ){
  sqlite3_stmt *pStmt = ((void*)0);
  int rc = 0;
  int rc2;
  const char *zLeftover;
  sqlite3 *db = pArg->db;
  unsigned char eStyle;
  sqlite3_qrf_spec spec;
  if( pzErrMsg ){
    *pzErrMsg = ((void*)0);
  }
  memcpy(&spec, &pArg->mode.spec, sizeof(spec));
  spec.xWrite = shellWriteQR;
  spec.pWriteArg = (void*)pArg;
  if( pArg->mode.eMode==7 && (((pArg)->shellFlgs & (0x00000008))!=0) ){
    spec.bTitles = 2;
  }
  ((void) (0));
  eStyle = aModeInfo[pArg->mode.eMode].eStyle;
  if( pArg->mode.bAutoScreenWidth ){
    spec.nScreenWidth = shellScreenWidth();
  }
  if( spec.eBlob==0 ){
    switch( spec.eText ){
      case 7: case 2: spec.eBlob = 2; break;
      case 6: spec.eBlob = 5; break;
      default: spec.eBlob = 1; break;
    }
  }
  if( pArg->expert.pExpert ){
    rc = expertHandleSQL(pArg, zSql, pzErrMsg);
    return expertFinish(pArg, (rc!=0), pzErrMsg);
  }
  while( zSql && zSql[0] && (0 == rc) ){
    static const char *zStmtSql;
    rc = sqlite3_prepare_v2(db, zSql, -1, &pStmt, &zLeftover);
    if( 0 != rc ){
      if( pzErrMsg ){
        *pzErrMsg = save_err_msg(db, "in prepare", rc, zSql);
      }
    }else{
      int isExplain;
      if( !pStmt ){
        zSql = zLeftover;
        while( ((*__ctype_b_loc ())[(int) (((unsigned char)zSql[0]))] & (unsigned short int) _ISspace) ) zSql++;
        continue;
      }
      zStmtSql = sqlite3_sql(pStmt);
      if( zStmtSql==0 ) zStmtSql = "";
      while( ((*__ctype_b_loc ())[(int) (((unsigned char)zStmtSql[0]))] & (unsigned short int) _ISspace) ) zStmtSql++;
      if( pArg ){
        pArg->pStmt = pStmt;
      }
      isExplain = sqlite3_stmt_isexplain(pStmt);
      if( pArg && pArg->mode.autoEQP && isExplain==0 && pArg->dot.nArg==0 ){
        int triggerEQP = 0;
        u8 savedEnableTimer = pArg->enableTimer;
        pArg->enableTimer = 0;
        disable_debug_trace_modes();
        sqlite3_db_config(db, 1008, -1, &triggerEQP);
        if( pArg->mode.autoEQP>=2 ){
          sqlite3_db_config(db, 1008, 1, 0);
        }
        sqlite3_reset(pStmt);
        spec.eStyle = 0;
        sqlite3_stmt_explain(pStmt, 2);
        sqlite3_format_query_result(pStmt, &spec, 0);
        if( pArg->mode.autoEQP>=3 ){
          sqlite3_reset(pStmt);
          sqlite3_stmt_explain(pStmt, 1);
          sqlite3_format_query_result(pStmt, &spec, 0);
        }
        if( pArg->mode.autoEQP>=2 && triggerEQP==0 ){
          sqlite3_db_config(db, 1008, 0, 0);
        }
        sqlite3_reset(pStmt);
        sqlite3_stmt_explain(pStmt, 0);
        restore_debug_trace_modes();
        pArg->enableTimer = savedEnableTimer;
      }
      bind_prepared_stmt(pArg, pStmt);
      if( isExplain && pArg->mode.autoExplain ){
        spec.eStyle = isExplain==1 ? 6 : 5;
        sqlite3_format_query_result(pStmt, &spec, pzErrMsg);
      }else if( pArg->mode.eMode==22 ){
        cli_printf(pArg->out, "</PRE>\n" "<TABLE border='1' cellspacing='0' cellpadding='2'>\n");
        spec.eStyle = 7;
        sqlite3_format_query_result(pStmt, &spec, pzErrMsg);
        cli_printf(pArg->out, "</TABLE>\n" "<PRE>");
      }else{
        spec.eStyle = eStyle;
        sqlite3_format_query_result(pStmt, &spec, pzErrMsg);
      }
      if( pArg && pArg->statsOn ){
        display_stats(db, pArg, 0);
      }
      if( pArg && pArg->mode.scanstatsOn ){
        char *zErr = 0;
        switch( pArg->mode.scanstatsOn ){
          case 1: spec.eStyle = 16; break;
          case 2: spec.eStyle = 17; break;
          default: spec.eStyle = 18; break;
        }
        sqlite3_reset(pStmt);
        rc = sqlite3_format_query_result(pStmt, &spec, &zErr);
        if( rc ){
          cli_printf(stderr, "Stats query failed: %s\n", zErr);
          sqlite3_free(zErr);
        }
      }
      rc2 = sqlite3_finalize(pStmt);
      if( rc!=7 ) rc = rc2;
      if( rc==0 ){
        zSql = zLeftover;
        while( ((*__ctype_b_loc ())[(int) (((unsigned char)zSql[0]))] & (unsigned short int) _ISspace) ) zSql++;
      }else if( pzErrMsg ){
        *pzErrMsg = save_err_msg(db, "stepping", rc, 0);
      }
      if( pArg ){
        pArg->pStmt = ((void*)0);
      }
    }
  }
  return rc;
}

