static int testcase_glob(const char *zGlob, const char *z){
  int c, c2;
  int invert;
  int seen;
  while( (c = (*(zGlob++)))!=0 ){
    if( ((*__ctype_b_loc ())[(int) (((unsigned char)c))] & (unsigned short int) _ISspace) ){
