      while( ((*__ctype_b_loc ())[(int) (((unsigned char)*z))] & (unsigned short int) _ISspace) ) z++;
    }else if( c=='*' ){
      while( (c=(*(zGlob++))) == '*' || c=='?' ){
        if( c=='?' && (*(z++))==0 ) return 0;
      }
      if( c==0 ){
        return 1;
      }else if( c=='[' ){
        while( *z && testcase_glob(zGlob-1,z)==0 ){
          z++;
        }
        return (*z)!=0;
      }
      while( (c2 = (*(z++)))!=0 ){
        while( c2!=c ){
          c2 = *(z++);
          if( c2==0 ) return 0;
        }
        if( testcase_glob(zGlob,z) ) return 1;
      }
      return 0;
    }else if( c=='?' ){
      if( (*(z++))==0 ) return 0;
    }else if( c=='[' ){
      int prior_c = 0;
      seen = 0;
      invert = 0;
      c = *(z++);
      if( c==0 ) return 0;
      c2 = *(zGlob++);
      if( c2=='^' ){
        invert = 1;
        c2 = *(zGlob++);
      }
      if( c2==']' ){
        if( c==']' ) seen = 1;
        c2 = *(zGlob++);
      }
      while( c2 && c2!=']' ){
        if( c2=='-' && zGlob[0]!=']' && zGlob[0]!=0 && prior_c>0 ){
          c2 = *(zGlob++);
          if( c>=prior_c && c<=c2 ) seen = 1;
          prior_c = 0;
        }else{
          if( c==c2 ){
            seen = 1;
          }
          prior_c = c2;
        }
        c2 = *(zGlob++);
      }
      if( c2==0 || (seen ^ invert)==0 ) return 0;
    }else if( c=='#' ){
      if( (z[0]=='-' || z[0]=='+') && ((*__ctype_b_loc ())[(int) (((unsigned char)z[1]))] & (unsigned short int) _ISdigit) ) z++;
      if( !((*__ctype_b_loc ())[(int) (((unsigned char)z[0]))] & (unsigned short int) _ISdigit) ) return 0;
      z++;
      while( ((*__ctype_b_loc ())[(int) (((unsigned char)z[0]))] & (unsigned short int) _ISdigit) ){ z++; }
    }else{
      if( c!=(*(z++)) ) return 0;
    }
  }
  while( ((*__ctype_b_loc ())[(int) (((unsigned char)*z))] & (unsigned short int) _ISspace) ){ z++; }
  return *z==0;
}

