    for(i=0; i<3; i++){
      if( pAr->bDryRun>=2 ){
        cli_printf(pAr->out, "*** BEGIN PASS %d ***\n", i+1);
      }
      j = sqlite3_bind_parameter_index(pSql, "$pass");
      sqlite3_bind_int(pSql, j, i);
      if( pAr->bDryRun && i==0 ){
        cli_printf(pAr->out, "%s\n", sqlite3_sql(pSql));
      }
      while( rc==0 && 100==sqlite3_step(pSql) ){
        if( i==0 && pAr->bVerbose ){
