static int arCreateOrUpdateCommand( ArCommand *pAr, int bUpdate, int bOnlyIfChanged ){
  const char *zCreate = "CREATE TABLE IF NOT EXISTS sqlar(\n" "  name TEXT PRIMARY KEY,  -- name of the file\n" "  mode INT,               -- access permissions\n" "  mtime INT,              -- last modification time\n" "  sz INT,                 -- original file size\n" "  data BLOB               -- compressed content\n" ")";
  const char *zDrop = "DROP TABLE IF EXISTS sqlar";
  const char *zInsertFmt[2] = {
     "REPLACE INTO %s(name,mode,mtime,sz,data)\n" "  SELECT\n" "    %s,\n" "    mode,\n" "    mtime,\n" "    CASE substr(lsmode(mode),1,1)\n" "      WHEN '-' THEN length(data)\n" "      WHEN 'd' THEN 0\n" "      ELSE -1 END,\n" "    sqlar_compress(data)\n" "  FROM fsdir(%Q,%Q) AS disk\n" "  WHERE lsmode(mode) NOT LIKE '?%%'%s;" , "REPLACE INTO %s(name,mode,mtime,data)\n" "  SELECT\n" "    %s,\n" "    mode,\n" "    mtime,\n" "    data\n" "  FROM fsdir(%Q,%Q) AS disk\n" "  WHERE lsmode(mode) NOT LIKE '?%%'%s;" };
  int i;
  int rc;
  const char *zTab = 0;
  char *zSql;
  char zTemp[50];
  char *zExists = 0;
  arExecSql(pAr, "PRAGMA page_size=512");
  rc = arExecSql(pAr, "SAVEPOINT ar;");
  if( rc!=0 ) return rc;
  zTemp[0] = 0;
  if( pAr->bZip ){
    if( pAr->zFile ){
      sqlite3_uint64 r;
      sqlite3_randomness(sizeof(r),&r);
      sqlite3_snprintf(sizeof(zTemp),zTemp,"zip%016llx",r);
      zTab = zTemp;
      zSql = sqlite3_mprintf( "CREATE VIRTUAL TABLE temp.%s USING zipfile(%Q)", zTab, pAr->zFile );
      rc = arExecSql(pAr, zSql);
      sqlite3_free(zSql);
    }else{
      zTab = "zip";
    }
  }else{
    zTab = "sqlar";
    if( bUpdate==0 ){
      rc = arExecSql(pAr, zDrop);
      if( rc!=0 ) goto end_ar_transaction;
    }
    rc = arExecSql(pAr, zCreate);
  }
  if( bOnlyIfChanged ){
    zExists = sqlite3_mprintf( " AND NOT EXISTS(" "SELECT 1 FROM %s AS mem" " WHERE mem.name=disk.name" " AND mem.mtime=disk.mtime" " AND mem.mode=disk.mode)", zTab);
  }else{
    zExists = sqlite3_mprintf("");
  }
  if( zExists==0 ) rc = 7;
  for(i=0; i<pAr->nArg && rc==0; i++){
    char *zSql2 = sqlite3_mprintf(zInsertFmt[pAr->bZip], zTab, pAr->bVerbose ? "shell_putsnl(name)" : "name", pAr->azArg[i], pAr->zDir, zExists);
    rc = arExecSql(pAr, zSql2);
    sqlite3_free(zSql2);
  }
end_ar_transaction: if( rc!=0 ){
    sqlite3_exec(pAr->db, "ROLLBACK TO ar; RELEASE ar;", 0, 0, 0);
  }else{
    rc = arExecSql(pAr, "RELEASE ar;");
    if( pAr->bZip && pAr->zFile ){
      zSql = sqlite3_mprintf("DROP TABLE %s", zTemp);
      arExecSql(pAr, zSql);
      sqlite3_free(zSql);
    }
  }
  sqlite3_free(zExists);
  return rc;
}

static int arDotCommand( ShellState *pState, int fromCmdLine, char **azArg, int nArg ){
  ArCommand cmd;
  int rc;
  memset(&cmd, 0, sizeof(cmd));
  cmd.fromCmdLine = fromCmdLine;
  rc = arParseCommand(azArg, nArg, &cmd);
  if( rc==0 ){
    int eDbType = 0;
    cmd.p = pState;
    cmd.out = pState->out;
    cmd.db = pState->db;
    if( cmd.zFile ){
      eDbType = deduceDatabaseType(cmd.zFile, 1, 0);
    }else{
      eDbType = pState->openMode;
    }
    if( eDbType==3 ){
      if( cmd.eCmd==4 || cmd.eCmd==5 ){
        if( cmd.zFile==0 ){
          cmd.zSrcTable = sqlite3_mprintf("zip");
        }else{
          cmd.zSrcTable = sqlite3_mprintf("zipfile(%Q)", cmd.zFile);
        }
      }
      cmd.bZip = 1;
    }else if( cmd.zFile ){
      int flags;
      if( cmd.bAppend ) eDbType = 2;
      if( cmd.eCmd==1 || cmd.eCmd==3 || cmd.eCmd==7 || cmd.eCmd==2 ){
        flags = 0x00000002|0x00000004;
      }else{
        flags = 0x00000001;
      }
      cmd.db = 0;
      if( cmd.bDryRun ){
        cli_printf(cmd.out, "-- open database '%s'%s\n", cmd.zFile, eDbType==2 ? " using 'apndvfs'" : "");
      }
      rc = sqlite3_open_v2(cmd.zFile, &cmd.db, flags, eDbType==2 ? "apndvfs" : 0);
      if( rc!=0 ){
        cli_printf(stderr, "cannot open file: %s (%s)\n", cmd.zFile, sqlite3_errmsg(cmd.db));
        goto end_ar_command;
      }
      sqlite3_fileio_init(cmd.db, 0, 0);
      sqlite3_sqlar_init(cmd.db, 0, 0);
      sqlite3_create_function(cmd.db, "shell_putsnl", 1, 1, cmd.p, shellPutsFunc, 0, 0);
    }
    if( cmd.zSrcTable==0 && cmd.bZip==0 && cmd.eCmd!=6 ){
      if( cmd.eCmd!=1 && sqlite3_table_column_metadata(cmd.db,0,"sqlar","name",0,0,0,0,0) ){
        cli_printf(stderr, "database does not contain an 'sqlar' table\n");
        rc = 1;
        goto end_ar_command;
      }
      cmd.zSrcTable = sqlite3_mprintf("sqlar");
    }
    switch( cmd.eCmd ){
      case 1: rc = arCreateOrUpdateCommand(&cmd, 0, 0);
        break;
      case 4: rc = arExtractCommand(&cmd);
        break;
      case 5: rc = arListCommand(&cmd);
        break;
      case 6: arUsage(pState->out);
        break;
      case 3: rc = arCreateOrUpdateCommand(&cmd, 1, 0);
        break;
      case 7: rc = arRemoveCommand(&cmd);
        break;
      default: ((void) (0));
        rc = arCreateOrUpdateCommand(&cmd, 1, 1);
        break;
    }
  }
end_ar_command: if( cmd.db!=pState->db ){
    close_db(cmd.db);
  }
  sqlite3_free(cmd.zSrcTable);
  return rc;
}

