static int recoverDatabaseCmd(ShellState *pState, int nArg, char **azArg){
  int rc = 0;
  const char *zRecoveryDb = "";
  const char *zLAF = "lost_and_found";
  int bFreelist = 1;
  int bRowids = 1;
  sqlite3_recover *p = 0;
  int i = 0;
  for(i=1; i<nArg; i++){
    char *z = azArg[i];
    int n;
    if( z[0]=='-' && z[1]=='-' ) z++;
    n = strlen30(z);
    if( n<=17 && memcmp("-ignore-freelist", z, n)==0 ){
      bFreelist = 0;
    }else if( n<=12 && memcmp("-recovery-db", z, n)==0 && i<(nArg-1) ){
      i++;
      zRecoveryDb = azArg[i];
    }else if( n<=15 && memcmp("-lost-and-found", z, n)==0 && i<(nArg-1) ){
      i++;
      zLAF = azArg[i];
    }else if( n<=10 && memcmp("-no-rowids", z, n)==0 ){
      bRowids = 0;
    }
    else{
      cli_printf(stderr,"unexpected option: %s\n", azArg[i]);
      showHelp(pState->out, azArg[0]);
      return 1;
    }
  }
  p = sqlite3_recover_init_sql( pState->db, "main", recoverSqlCb, (void*)pState );
  if( !pState->bSafeMode ){
    sqlite3_recover_config(p, 789, (void*)zRecoveryDb);
  }
  sqlite3_recover_config(p, 1, (void*)zLAF);
  sqlite3_recover_config(p, 3, (void*)&bRowids);
  sqlite3_recover_config(p, 2,(void*)&bFreelist);
  cli_printf(pState->out, ".dbconfig defensive off\n");
  sqlite3_recover_run(p);
  if( sqlite3_recover_errcode(p)!=0 ){
    const char *zErr = sqlite3_recover_errmsg(p);
    int errCode = sqlite3_recover_errcode(p);
    cli_printf(stderr,"sql error: %s (%d)\n", zErr, errCode);
  }
  rc = sqlite3_recover_finish(p);
  return rc;
}

static int intckDatabaseCmd(ShellState *pState, i64 nStepPerUnlock){
  sqlite3_intck *p = 0;
  int rc = 0;
  rc = sqlite3_intck_open(pState->db, "main", &p);
  if( rc==0 ){
    i64 nStep = 0;
    i64 nError = 0;
    const char *zErr = 0;
    while( 0==sqlite3_intck_step(p) ){
      const char *zMsg = sqlite3_intck_message(p);
      if( zMsg ){
        cli_printf(pState->out, "%s\n", zMsg);
        nError++;
      }
      nStep++;
      if( nStepPerUnlock && (nStep % nStepPerUnlock)==0 ){
        sqlite3_intck_unlock(p);
      }
    }
    rc = sqlite3_intck_error(p, &zErr);
    if( zErr ){
      cli_printf(stderr,"%s\n", zErr);
    }
    sqlite3_intck_close(p);
    cli_printf(pState->out, "%lld steps, %lld errors\n", nStep, nError);
  }
  return rc;
}

