    rc_err_oom_die(rc);
    rc = sqlite3_step(pStmt);
    rc_err_oom_die(rc);
    sqlite3_finalize(pStmt);
    return 0;
  }else if( *pDb==0 ){
    return 0;
  }else{
    char *zColsSpec = 0;
    int hasDupes = db_int(*pDb, "%s", zHasDupes);
    int nDigits = (hasDupes)? db_int(*pDb, "%s", zColDigits) : 0;
    if( hasDupes ){
      rc = sqlite3_exec(*pDb, zSetReps, 0, 0, 0);
      rc_err_oom_die(rc);
      rc = sqlite3_prepare_v2(*pDb, zRenameRank, -1, &pStmt, 0);
      rc_err_oom_die(rc);
      sqlite3_bind_int(pStmt, 1, nDigits);
      rc = sqlite3_step(pStmt);
      sqlite3_finalize(pStmt);
      if( rc!=101 ) rc_err_oom_die(7);
    }
    ((void) (0));
    rc = sqlite3_prepare_v2(*pDb, zCollectVar, -1, &pStmt, 0);
    rc_err_oom_die(rc);
    rc = sqlite3_step(pStmt);
    if( rc==100 ){
      zColsSpec = sqlite3_mprintf("%s", sqlite3_column_text(pStmt, 0));
    }else{
      zColsSpec = 0;
    }
    if( pzRenamed!=0 ){
      if( !hasDupes ) *pzRenamed = 0;
      else{
        sqlite3_finalize(pStmt);
        if( 0==sqlite3_prepare_v2(*pDb, zRenamesDone, -1, &pStmt, 0) && 100==sqlite3_step(pStmt) ){
          *pzRenamed = sqlite3_mprintf("%s", sqlite3_column_text(pStmt, 0));
        }else *pzRenamed = 0;
      }
    }
    sqlite3_finalize(pStmt);
    sqlite3_close(*pDb);
    *pDb = 0;
    return zColsSpec;
  }
}

static int outputDumpWarning(ShellState *p, const char *zLike){
  int rc = 0;
  sqlite3_stmt *pStmt = 0;
  shellPreparePrintf(p->db, &rc, &pStmt, "SELECT 1 FROM sqlite_schema o WHERE " "sql LIKE 'CREATE VIRTUAL TABLE%%' AND (%s)", zLike ? zLike : "true" );
  if( rc==0 && sqlite3_step(pStmt)==100 ){
    cli_puts("/* WARNING: " "Script requires that SQLITE_DBCONFIG_DEFENSIVE be disabled */\n", p->out );
  }
  shellFinalize(&rc, pStmt);
  return rc;
}

static int faultsim_callback(int iArg){
  if( faultsim_state.iId>0 && faultsim_state.iId!=iArg ){
    return 0;
  }
  if( faultsim_state.iCnt ){
    if( faultsim_state.iCnt>0 ) faultsim_state.iCnt--;
    if( faultsim_state.eVerbose>=2 ){
      cli_printf(stdout, "FAULT-SIM id=%d no-fault (cnt=%d)\n", iArg, faultsim_state.iCnt);
    }
    return 0;
  }
  if( faultsim_state.eVerbose>=1 ){
    cli_printf(stdout, "FAULT-SIM id=%d returns %d\n", iArg, faultsim_state.iErr);
  }
  faultsim_state.iCnt = faultsim_state.iInterval;
  faultsim_state.nHit++;
  if( faultsim_state.nRepeat>0 && faultsim_state.nRepeat<=faultsim_state.nHit ){
    faultsim_state.iCnt = -1;
  }
  return faultsim_state.iErr;
}

static int dotCmdImport(ShellState *p){
  int nArg = p->dot.nArg;
  char **azArg = p->dot.azArg;
  char *zTable = 0;
  char *zSchema = 0;
  char *zFile = 0;
  sqlite3_stmt *pStmt = ((void*)0);
  int nCol;
  i64 nByte;
  int i, j;
  int needCommit;
  char *zSql = 0;
  ImportCtx sCtx;
  char *( *xRead)(ImportCtx*);
  int eVerbose = 0;
  i64 nSkip = 0;
  i64 iLineOffset = 0;
  char *zCreate = 0;
  int rc;
  failIfSafeMode(p, "cannot run .import in safe mode");
  memset(&sCtx, 0, sizeof(sCtx));
  if( p->mode.eMode==0 ){
    xRead = ascii_read_one_field;
  }else{
    xRead = csv_read_one_field;
  }
  for(i=1; i<nArg; i++){
    char *z = azArg[i];
    if( z[0]=='-' && z[1]=='-' ) z++;
    if( z[0]!='-' ){
      if( zFile==0 ){
        zFile = z;
      }else if( zTable==0 ){
        zTable = z;
      }else{
        dotCmdError(p, i, "unknown argument", 0);
        return 1;
      }
    }else if( cli_strcmp(z,"-v")==0 ){
      eVerbose++;
    }else if( cli_strcmp(z,"-schema")==0 && i<nArg-1 ){
      zSchema = azArg[++i];
    }else if( cli_strcmp(z,"-skip")==0 && i<nArg-1 ){
      nSkip = integerValue(azArg[++i]);
    }else if( cli_strcmp(z,"-ascii")==0 ){
      if( sCtx.cColSep==0 ) sCtx.cColSep = '\037';
      if( sCtx.cRowSep==0 ) sCtx.cRowSep = '\036';
      xRead = ascii_read_one_field;
    }else if( cli_strcmp(z,"-csv")==0 ){
      if( sCtx.cColSep==0 ) sCtx.cColSep = ',';
      if( sCtx.cRowSep==0 ) sCtx.cRowSep = '\n';
      xRead = csv_read_one_field;
    }else if( cli_strcmp(z,"-esc")==0 ){
      sCtx.cUQEscape = azArg[++i][0];
    }else if( cli_strcmp(z,"-qesc")==0 ){
      sCtx.cQEscape = azArg[++i][0];
    }else if( cli_strcmp(z,"-colsep")==0 ){
      if( i==nArg-1 ){
        dotCmdError(p, i, "missing argument", 0);
        return 1;
      }
      i++;
      sCtx.cColSep = azArg[i][0];
    }else if( cli_strcmp(z,"-rowsep")==0 ){
      if( i==nArg-1 ){
        dotCmdError(p, i, "missing argument", 0);
        return 1;
      }
      i++;
      sCtx.cRowSep = azArg[i][0];
    }else{
      dotCmdError(p, i, "unknown option", 0);
      return 1;
    }
  }
  if( zTable==0 ){
    dotCmdError(p, nArg, 0, "Missing %s argument\n", zFile==0 ? "FILE" : "TABLE");
    return 1;
  }
  seenInterrupt = 0;
  open_db(p, 0);
  if( sCtx.cColSep==0 ){
    if( p->mode.spec.zColumnSep && p->mode.spec.zColumnSep[0]!=0 ){
      sCtx.cColSep = p->mode.spec.zColumnSep[0];
    }else{
      sCtx.cColSep = ',';
    }
  }
  if( (sCtx.cColSep & 0x80)!=0 ){
    cli_puts("Error: .import column separator must be ASCII\n",stderr);
    return 1;
  }
  if( sCtx.cRowSep==0 ){
    if( p->mode.spec.zRowSep && p->mode.spec.zRowSep[0]!=0 ){
      sCtx.cRowSep = p->mode.spec.zRowSep[0];
    }else{
      sCtx.cRowSep = '\n';
    }
  }
  if( sCtx.cRowSep=='\r' && xRead!=ascii_read_one_field ){
    sCtx.cRowSep = '\n';
  }
  if( (sCtx.cRowSep & 0x80)!=0 ){
    cli_puts("Error: .import row separator must be ASCII\n",stderr);
    return 1;
  }
  sCtx.zFile = zFile;
  sCtx.nLine = 1;
  if( sCtx.zFile[0]=='|' ){
    sCtx.in = popen(sCtx.zFile+1, "r");
    sCtx.zFile = "<pipe>";
    sCtx.xCloser = pclose;
  }else if( sCtx.zFile[0]=='<' && sCtx.zFile[1]=='<' && sCtx.zFile[2]!=0 ){
    int nEndMark = strlen30(zFile)-2;
    char *zEndMark = &zFile[2];
    sqlite3_str *pContent = sqlite3_str_new(p->db);
    int ckEnd = 1;
    i64 iStart = p->lineno;
    char zLine[2000];
    sCtx.zFile = p->zInFile;
    sCtx.nLine = p->lineno+1;
    iLineOffset = p->lineno;
    while( fgets(zLine,sizeof(zLine),p->in) ){
      if( ckEnd && cli_strncmp(zLine,zEndMark,nEndMark)==0 ){
        ckEnd = 2;
        if( strchr(zLine,'\n') ) p->lineno++;
        break;
      }
      if( strchr(zLine,'\n') ){
        p->lineno++;
        ckEnd = 1;
      }else{
        ckEnd = 0;
      }
      sqlite3_str_appendall(pContent, zLine);
    }
    sCtx.zIn = sqlite3_str_finish(pContent);
    if( sCtx.zIn==0 ){
      sCtx.zIn = sqlite3_mprintf("");
    }
    if( ckEnd<2 ){
      i64 savedLn = p->lineno;
      p->lineno = iStart;
      dotCmdError(p, 0, 0,"Content terminator \"%s\" not found.",zEndMark);
      p->lineno = savedLn;
      import_cleanup(&sCtx);
      return 1;
    }
  }else{
    sCtx.in = fopen(sCtx.zFile, "rb");
    sCtx.xCloser = fclose;
  }
  if( sCtx.in==0 && sCtx.zIn==0 ){
    dotCmdError(p, 0, 0, "cannot open \"%s\"", zFile);
    import_cleanup(&sCtx);
    return 1;
  }
  if( eVerbose>=1 ){
    char zSep[2];
    zSep[1] = 0;
    zSep[0] = sCtx.cColSep;
    cli_puts("Column separator ", p->out);
    output_c_string(p->out, zSep);
    cli_puts(", row separator ", p->out);
    zSep[0] = sCtx.cRowSep;
    output_c_string(p->out, zSep);
    cli_puts("\n", p->out);
  }
  sCtx.z = sqlite3_malloc64(120);
  if( sCtx.z==0 ){
    import_cleanup(&sCtx);
    shell_out_of_memory();
  }
  while( nSkip>0 ){
    nSkip--;
    while( xRead(&sCtx) && sCtx.cTerm==sCtx.cColSep ){}
  }
  import_append_char(&sCtx, 0);
  if( sqlite3_table_column_metadata(p->db, zSchema, zTable,0,0,0,0,0,0) && 0==db_int(p->db, "SELECT count(*) FROM \"%w\".sqlite_schema" " WHERE name=%Q AND type='view'", zSchema ? zSchema : "main", zTable) ){
    sqlite3 *dbCols = 0;
    char *zRenames = 0;
    char *zColDefs;
    zCreate = sqlite3_mprintf("CREATE TABLE \"%w\".\"%w\"", zSchema ? zSchema : "main", zTable);
    while( xRead(&sCtx) ){
      zAutoColumn(sCtx.z, &dbCols, 0);
      if( sCtx.cTerm!=sCtx.cColSep ) break;
    }
    zColDefs = zAutoColumn(0, &dbCols, &zRenames);
    if( zRenames!=0 ){
      cli_printf((stdin_is_interactive && p->in==stdin)? p->out : stderr, "Columns renamed during .import %s due to duplicates:\n" "%s\n", sCtx.zFile, zRenames);
      sqlite3_free(zRenames);
    }
    ((void) (0));
    if( zColDefs==0 ){
      cli_printf(stderr,"%s: empty file\n", sCtx.zFile);
      import_cleanup(&sCtx);
      sqlite3_free(zCreate);
      return 1;
    }
    zCreate = sqlite3_mprintf("%z%z\n", zCreate, zColDefs);
    if( zCreate==0 ){
      import_cleanup(&sCtx);
      shell_out_of_memory();
    }
    if( eVerbose>=1 ){
      cli_printf(p->out, "%s\n", zCreate);
    }
    rc = sqlite3_exec(p->db, zCreate, 0, 0, 0);
    if( rc ){
      cli_printf(stderr, "%s failed:\n%s\n", zCreate, sqlite3_errmsg(p->db));
    }
    sqlite3_free(zCreate);
    zCreate = 0;
    if( rc ){
      import_cleanup(&sCtx);
      return 1;
    }
  }
  zSql = sqlite3_mprintf("SELECT count(*) FROM pragma_table_info(%Q,%Q);", zTable, zSchema);
  if( zSql==0 ){
    import_cleanup(&sCtx);
    shell_out_of_memory();
  }
  rc = sqlite3_prepare_v2(p->db, zSql, -1, &pStmt, 0);
  sqlite3_free(zSql);
  zSql = 0;
  if( rc ){
    if (pStmt) sqlite3_finalize(pStmt);
    shellDatabaseError(p->db);
    import_cleanup(&sCtx);
    return 1;
  }
  if( sqlite3_step(pStmt)==100 ){
    nCol = sqlite3_column_int(pStmt, 0);
  }else{
    nCol = 0;
  }
  sqlite3_finalize(pStmt);
  pStmt = 0;
  if( nCol==0 ) return 0;
  nByte = 64 + (zSchema ? strlen(zSchema)*2 + 2: 0) + strlen(zTable)*2 + 2 + nCol*2;
  zSql = sqlite3_malloc64( nByte );
  if( zSql==0 ){
    import_cleanup(&sCtx);
    shell_out_of_memory();
  }
  if( zSchema ){
    sqlite3_snprintf(nByte, zSql, "INSERT INTO \"%w\".\"%w\" VALUES(?", zSchema, zTable);
  }else{
    sqlite3_snprintf(nByte, zSql, "INSERT INTO \"%w\" VALUES(?", zTable);
  }
  j = strlen30(zSql);
  for(i=1; i<nCol; i++){
    zSql[j++] = ',';
    zSql[j++] = '?';
  }
  zSql[j++] = ')';
  zSql[j] = 0;
  ((void) (0));
  if( eVerbose>=2 ){
    cli_printf(p->out, "Insert using: %s\n", zSql);
  }
  rc = sqlite3_prepare_v2(p->db, zSql, -1, &pStmt, 0);
  sqlite3_free(zSql);
  zSql = 0;
  if( rc ){
    shellDatabaseError(p->db);
    if (pStmt) sqlite3_finalize(pStmt);
    import_cleanup(&sCtx);
    return 1;
  }
  needCommit = sqlite3_get_autocommit(p->db);
  if( needCommit ) sqlite3_exec(p->db, "BEGIN", 0, 0, 0);
  do{
    int startLine = sCtx.nLine;
    for(i=0; i<nCol; i++){
      char *z = xRead(&sCtx);
      if( z==0 && i==0 ) break;
      if( p->mode.eMode==0 && (z==0 || z[0]==0) && i==0 ) break;
      if( z==0 && (xRead==csv_read_one_field) && i==nCol-1 && i>0 ){
        z = "";
      }
      sqlite3_bind_text(pStmt, i+1, z, -1, ((sqlite3_destructor_type)-1));
      if( i<nCol-1 && sCtx.cTerm!=sCtx.cColSep ){
        if( i==0 && (strcmp(z,"\n")==0 || strcmp(z,"\r\n")==0) ){
          break;
        }
        cli_printf(stderr,"%s:%d: expected %d columns but found %d" " - filling the rest with NULL\n", sCtx.zFile, startLine, nCol, i+1);
        i += 2;
        while( i<=nCol ){ sqlite3_bind_null(pStmt, i); i++; }
      }
    }
    if( sCtx.cTerm==sCtx.cColSep ){
      do{
        xRead(&sCtx);
        i++;
      }while( sCtx.cTerm==sCtx.cColSep );
      cli_printf(stderr, "%s:%d: expected %d columns but found %d - extras ignored\n", sCtx.zFile, startLine, nCol, i);
    }
    if( i>=nCol ){
      sqlite3_step(pStmt);
      rc = sqlite3_reset(pStmt);
      if( rc!=0 ){
        cli_printf(stderr,"%s:%d: INSERT failed: %s\n", sCtx.zFile, startLine, sqlite3_errmsg(p->db));
        sCtx.nErr++;
        if( bail_on_error ) break;
      }else{
        sCtx.nRow++;
      }
    }
  }while( sCtx.cTerm!=(-1) );
  import_cleanup(&sCtx);
  sqlite3_finalize(pStmt);
  if( needCommit ) sqlite3_exec(p->db, "COMMIT", 0, 0, 0);
  if( eVerbose>0 ){
    cli_printf(p->out, "Added %d rows with %d errors using %d lines of input\n", sCtx.nRow, sCtx.nErr, sCtx.nLine-1-iLineOffset);
  }
  return sCtx.nErr ? 1 : 0;
}

static int modeTitleDsply(ShellState *p, int bAll){
  int eMode = p->mode.eMode;
  const ModeInfo *pI = &aModeInfo[eMode];
  int bT = p->mode.spec.bTitles;
  int eT = p->mode.spec.eTitle;
  int bH = pI->bHdr;
  int eH = pI->eHdr;
  sqlite3_uint64 v = 0x0133013311220102UL;
  if( bH==0 ) return 0;
  if( eT==0 ) eT = eH;
  if( bT==0 ) bT = bH;
  if( eT!=eH ) v >>= 32;
  if( bT!=bH ) v >>= 16;
  if( bT<2 ) v >>= 8;
  if( !bAll ) v >>= 4;
  v &= 3;
  if( p->mode.spec.bTitles==3 ){
    if( v==3 ) v = 5;
    if( v==2 ) v = 3;
  }else{
    if( v==3 ) v = 4;
  }
  return v;
}

static int dotCmdMode(ShellState *p){
  int nArg = p->dot.nArg;
  char **azArg = p->dot.azArg;
  int eMode = -1;
  int iMode = -1;
  int i;
  int k;
  int chng = 0;
  int bAll = 0;
  for(i=1; i<nArg; i++){
    const char *z = azArg[i];
    if( z[0]=='-' && z[1]=='-' ) z++;
    if( z[0]!='-' && iMode<0 && (eMode = modeFind(p, azArg[i]))>=0 && eMode!=22 ){
      iMode = i;
      modeChange(p, eMode);
      if( i+1<nArg && azArg[i+1][0]!='-' ){
        i++;
        modeSetStr(&p->mode.spec.zTableName, azArg[i]);
      }
      chng = 1;
    }else if( optionMatch(z,"align") ){
      char *zAlign;
      int nAlign;
      int nErr = 0;
      if( i+1>=nArg ){
        dotCmdError(p, i, "missing argument", 0);
        return 1;
      }
      i++;
      zAlign = azArg[i];
      nAlign = 0x3fff & strlen(zAlign);
      free(p->mode.spec.aAlign);
      p->mode.spec.aAlign = malloc(nAlign);
      shell_check_oom(p->mode.spec.aAlign);
      for(k=0; k<nAlign; k++){
        unsigned char c = 0;
        switch( zAlign[k] ){
          case 'l': case 'L': c = 1; break;
          case 'c': case 'C': c = 2; break;
          case 'r': case 'R': c = 3; break;
          default: nErr++; break;
        }
        p->mode.spec.aAlign[k] = c;
      }
      p->mode.spec.nAlign = nAlign;
      chng = 1;
      if( nErr ){
        dotCmdError(p, i, "bad alignment string", "Should contain only characters L, C, and R.");
        return 1;
      }
    }else if( pickStr(z,0,"-blob","-blob-quote","")>=0 ){
      if( (++i)>=nArg ){
        dotCmdError(p, i-1, "missing argument", 0);
        return 1;
      }
      k = pickStr(azArg[i], 0, "auto", "text", "sql", "hex", "tcl", "json", "size", "");
      if( k>=0 ){
        p->mode.spec.eBlob = k & 0xff;
      }
      chng = 1;
    }else if( optionMatch(z,"border") ){
      if( (++i)>=nArg ){
        dotCmdError(p, i-1, "missing argument", 0);
        return 1;
      }
      k = pickStr(azArg[i], 0, "auto", "off", "on", "");
      if( k>=0 ){
        p->mode.spec.bBorder = k & 0x3;
      }
      chng = 1;
    }else if( 0<=(k=pickStr(z,0, "-charlimit","-linelimit","-titlelimit","-multiinsert","")) ){
      int w;
      if( i+1>=nArg ){
        dotCmdError(p, i, "missing argument", 0);
        return 1;
      }
      w = integerValue(azArg[++i]);
      switch( k ){
        case 0: p->mode.spec.nCharLimit = w; break;
        case 1: p->mode.spec.nLineLimit = w; break;
        case 2: p->mode.spec.nTitleLimit = w; break;
        default: p->mode.spec.nMultiInsert = w; break;
      }
      chng = 1;
    }else if( 0<=(k=pickStr(z,0,"-tablename","-rowsep","-colsep","-null","")) ){
      if( i+1>=nArg ){
        dotCmdError(p, i, "missing argument", 0);
        return 1;
      }
      i++;
      switch( k ){
        case 0: modeSetStr(&p->mode.spec.zTableName, azArg[i]); break;
        case 1: modeSetStr(&p->mode.spec.zRowSep, azArg[i]); break;
        case 2: modeSetStr(&p->mode.spec.zColumnSep, azArg[i]); break;
        case 3: modeSetStr(&p->mode.spec.zNull, azArg[i]); break;
      }
      chng = 1;
    }else if( optionMatch(z,"escape") ){
      char *zErr = 0;
      if( (++i)>=nArg ){
        dotCmdError(p, i-1, "missing argument", 0);
        return 1;
      }
      k = pickStr(azArg[i],&zErr,"off","ascii","symbol","");
      if( k<0 ){
        dotCmdError(p, i, "unknown escape type", "%s", zErr);
        sqlite3_free(zErr);
        return 1;
      }
      p->mode.spec.eEsc = k+1;
      chng = 1;
    }else if( optionMatch(z,"limits") ){
      if( (++i)>=nArg ){
        dotCmdError(p, i-1, "missing argument", 0);
        return 1;
      }
      if( modeSetLimit(p, azArg[i]) ){
        dotCmdError(p, i, "bad argument", "Should be \"on\" or \"off\" or " "\"L,C,T\" where L, C, and T are unsigned integers");
        return 1;
      }
      chng = 1;
    }else if( optionMatch(z,"list") ){
      int ii;
      cli_puts("available modes:", p->out);
      for(ii=0; ii<(int)(sizeof(aModeInfo)/sizeof(aModeInfo[0])); ii++){
        if( ii==22 ) continue;
        cli_printf(p->out, " %s", aModeInfo[ii].zName);
      }
      for(ii=0; ii<p->nSavedModes; ii++){
        cli_printf(p->out, " %s", p->aSavedModes[ii].zTag);
      }
      cli_puts(" batch tty\n", p->out);
      chng = 1;
    }else if( optionMatch(z,"once") ){
      modePush(p);
      p->nPopMode = 1;
    }else if( optionMatch(z,"noquote") ){
      p->mode.spec.eText = 1;
      p->mode.spec.eBlob = 0;
      chng = 1;
    }else if( optionMatch(z,"quote") ){
      if( i+1<nArg && azArg[i+1][0]!='-' && (iMode>0 || strcmp(azArg[i+1],"off")==0 || modeFind(p, azArg[i+1])<0) ){
        i++;
        if( (k = pickStr(azArg[i],0,"no","yes","0","1",""))>=0 ){
          k &= 1;
        }else{
          char *zErr = 0;
          k = pickStr(azArg[i],&zErr, "off","on","sql","csv","html","tcl","json","relaxed","");
          if( k<0 ){
            dotCmdError(p, i, "unknown", "%z", zErr);
            return 1;
          }
        }
      }else{
        k = 1;
      }
      switch( k ){
        case 1: modeSetStr(&p->mode.spec.zNull, "NULL");
        case 2: p->mode.spec.eText = 2;
          break;
        case 3: p->mode.spec.eText = 3;
          break;
        case 4: p->mode.spec.eText = 4;
          break;
        case 5: p->mode.spec.eText = 5;
          break;
        case 6: p->mode.spec.eText = 6;
          break;
        case 7: p->mode.spec.eText = 7;
          break;
        default: p->mode.spec.eText = 1;
          break;
      }
      chng = 1;
    }else if( optionMatch(z,"reset") ){
      int saved_eMode = p->mode.eMode;
      modeFree(&p->mode);
      modeChange(p, saved_eMode);
    }else if( optionMatch(z,"rowcount") ){
      if( i+1>=nArg ){
        dotCmdError(p, i, "missing argument", 0);
        return 1;
      }
      p->mode.spec.bRowCount = booleanValue(azArg[++i]) ? 2 : 1;
      chng = 1;
    }else if( optionMatch(z,"screenwidth") || optionMatch(z,"sw") ){
      if( (++i)>=nArg ){
        dotCmdError(p, i-1, "missing argument", 0);
        return 1;
      }
      k = pickStr(azArg[i],0,"off","auto","");
      if( k==0 ){
        p->mode.bAutoScreenWidth = 0;
        p->mode.spec.nScreenWidth = 0;
      }else if( k==1 ){
        p->mode.bAutoScreenWidth = 1;
      }else{
        i64 w = integerValue(azArg[i]);
        p->mode.bAutoScreenWidth = 0;
        if( w<0 ) w = 0;
        if( w>10000 ) w = 10000;
        p->mode.spec.nScreenWidth = w;
      }
      chng = 1;
    }else if( optionMatch(z,"tag") ){
      size_t nByte;
      int n;
      const char *zTag;
      if( i+1>=nArg ){
        dotCmdError(p, i, "missing argument", 0);
        return 1;
      }
      zTag = azArg[++i];
      if( modeFind(p, zTag)>=0 ){
        dotCmdError(p, i, "mode already exists", 0);
        return 1;
      }
      if( p->nSavedModes > 25 ){
        dotCmdError(p, i-1, "cannot add more modes", 0);
        return 1;
      }
      n = p->nSavedModes++;
      nByte = sizeof(p->aSavedModes[0]);
      nByte *= n+1;
      p->aSavedModes = realloc( p->aSavedModes, nByte );
      shell_check_oom(p->aSavedModes);
      p->aSavedModes[n].zTag = strdup(zTag);
      shell_check_oom(p->aSavedModes[n].zTag);
      modeDup(&p->aSavedModes[n].mode, &p->mode);
      chng = 1;
    }else if( optionMatch(z,"textjsonb") ){
      if( i+1>=nArg ){
        dotCmdError(p, i, "missing argument", 0);
        return 1;
      }
      p->mode.spec.bTextJsonb = booleanValue(azArg[++i]) ? 2 : 1;
      chng = 1;
    }else if( optionMatch(z,"titles") || optionMatch(z,"title") ){
      char *zErr = 0;
      if( i+1>=nArg ){
        dotCmdError(p, i, "missing argument", 0);
        return 1;
      }
      k = pickStr(azArg[++i],&zErr, "off","on","always","auto","plain","sql","csv","html","tcl","json","");
      if( k<0 ){
        dotCmdError(p, i, "bad --titles value","%z", zErr);
        return 1;
      }
      p->mode.mFlags &= ~0x04;
      if( k<=2 ){
        p->mode.spec.bTitles = 1 +k;
      }else if( k==3 ){
        p->mode.spec.eTitle = aModeInfo[p->mode.eMode].eHdr;
        p->mode.spec.bTitles = aModeInfo[p->mode.eMode].bHdr;
      }else{
        p->mode.spec.eTitle = (k-4)+1;
        if( p->mode.spec.bTitles==1 ){
          p->mode.spec.bTitles = 3;
        }
      }
      chng = 1;
    }else if( optionMatch(z,"widths") || optionMatch(z,"width") ){
      int nWidth = 0;
      short int *aWidth;
      const char *zW;
      if( i+1>=nArg ){
        dotCmdError(p, i, "missing argument", 0);
        return 1;
      }
      zW = azArg[++i];
      aWidth = malloc( strlen(zW) );
      while( ((*__ctype_b_loc ())[(int) (((unsigned char)zW[0]))] & (unsigned short int) _ISspace) ) zW++;
      while( zW[0] ){
        int w = 0;
        int nDigit = 0;
        k = zW[0]=='-' && ((*__ctype_b_loc ())[(int) (((unsigned char)zW[1]))] & (unsigned short int) _ISdigit);
        while( ((*__ctype_b_loc ())[(int) (((unsigned char)zW[k]))] & (unsigned short int) _ISdigit) ){
          w = w*10 + zW[k] - '0';
          if( w>10000 ){
            dotCmdError(p,i+1,"width too big", "Maximum column width is %d", 10000);
            free(aWidth);
            return 1;
          }
          nDigit++;
          k++;
        }
        if( nDigit==0 ){
          dotCmdError(p,i+1,"syntax error", "should be a comma-separated list if integers");
          free(aWidth);
          return 1;
        }
        if( zW[0]=='-' ) w = -w;
        aWidth[nWidth++] = w;
        zW += k;
        if( zW[0]==',' ) zW++;
        while( ((*__ctype_b_loc ())[(int) (((unsigned char)zW[0]))] & (unsigned short int) _ISspace) ) zW++;
      }
      free(p->mode.spec.aWidth);
      p->mode.spec.aWidth = aWidth;
      p->mode.spec.nWidth = nWidth;
      chng = 1;
    }else if( optionMatch(z,"wrap") ){
      int w;
      if( i+1>=nArg ){
        dotCmdError(p, i, "missing argument", 0);
        return 1;
      }
      w = integerValue(azArg[++i]);
      if( w<(-10000) ) w = -10000;
      if( w>10000 ) w = 10000;
      p->mode.spec.nWrap = w;
      chng = 1;
    }else if( optionMatch(z,"ww") ){
      p->mode.spec.bWordWrap = 2;
      chng = 1;
    }else if( optionMatch(z,"wordwrap") ){
      if( i+1>=nArg ){
        dotCmdError(p, i, "missing argument", 0);
        return 1;
      }
      p->mode.spec.bWordWrap = (u8)booleanValue(azArg[++i]) ? 2 : 1;
      chng = 1;
    }else if( optionMatch(z,"v") || optionMatch(z,"verbose") ){
      bAll = 1;
    }else if( z[0]=='-' ){
      dotCmdError(p, i, "bad option", "Use \".help .mode\" for more info");
      return 1;
    }else{
      dotCmdError(p, i, iMode>0?"bad argument":"unknown mode", "Use \".help .mode\" for more info");
      return 1;
    }
  }
  if( !chng || bAll ){
    const ModeInfo *pI = aModeInfo + p->mode.eMode;
    sqlite3_str *pDesc = sqlite3_str_new(p->db);
    char *zDesc;
    const char *zSetting;
    if( p->nPopMode ) sqlite3_str_appendall(pDesc, "--once ");
    sqlite3_str_appendall(pDesc,pI->zName);
    if( bAll || (p->mode.spec.nAlign && pI->eCx==2) ){
      int ii;
      sqlite3_str_appendall(pDesc, " --align \"");
      for(ii=0; ii<p->mode.spec.nAlign; ii++){
        unsigned char a = p->mode.spec.aAlign[ii];
        sqlite3_str_appendchar(pDesc, 1, "LLCR"[a&3]);
      }
      sqlite3_str_append(pDesc, "\"", 1);
    }
    if( bAll || (p->mode.spec.bBorder==1) != ((pI->mFlg&1)!=0) ){
      sqlite3_str_appendf(pDesc," --border %s", p->mode.spec.bBorder==1 ? "off" : "on");
    }
    if( bAll || p->mode.spec.eBlob!=0 ){
      const char *azBQuote[] = { "auto", "text", "sql", "hex", "tcl", "json", "size" };
      u8 e = p->mode.spec.eBlob;
      sqlite3_str_appendf(pDesc, " --blob-quote %s", azBQuote[e]);
    }
    zSetting = aModeStr[pI->eCSep];
    if( bAll || (zSetting && cli_strcmp(zSetting,p->mode.spec.zColumnSep)!=0) ){
      sqlite3_str_appendf(pDesc, " --colsep ");
      append_c_string(pDesc, p->mode.spec.zColumnSep);
    }
    if( bAll || p->mode.spec.eEsc!=0 ){
      sqlite3_str_appendf(pDesc, " --escape %s",qrfEscNames[p->mode.spec.eEsc]);
    }
    if( bAll || (p->mode.spec.nLineLimit>0 && pI->eCx>0) || p->mode.spec.nCharLimit>0 || (p->mode.spec.nTitleLimit>0 && pI->eCx>0) ){
      if( p->mode.spec.nLineLimit==0 && p->mode.spec.nCharLimit==0 && p->mode.spec.nTitleLimit==0 ){
        sqlite3_str_appendf(pDesc, " --limits off");
      }else if( p->mode.spec.nLineLimit==5 && p->mode.spec.nCharLimit==300 && p->mode.spec.nTitleLimit==20 ){
        sqlite3_str_appendf(pDesc, " --limits on");
      }else{
        sqlite3_str_appendf(pDesc, " --limits %d,%d,%d", p->mode.spec.nLineLimit, p->mode.spec.nCharLimit, p->mode.spec.nTitleLimit);
      }
    }
    if( bAll || (p->mode.spec.nMultiInsert && p->mode.spec.eStyle==8) ){
      sqlite3_str_appendf(pDesc, " --multiinsert %u", p->mode.spec.nMultiInsert);
    }
    zSetting = aModeStr[pI->eNull];
    if( bAll || (zSetting && cli_strcmp(zSetting,p->mode.spec.zNull)!=0) ){
      sqlite3_str_appendf(pDesc, " --null ");
      append_c_string(pDesc, p->mode.spec.zNull);
    }
    if( bAll || (pI->eText!=p->mode.spec.eText && (pI->eText>1 || p->mode.spec.eText>1)) ){
      sqlite3_str_appendf(pDesc," --quote %s",qrfQuoteNames[p->mode.spec.eText]);
    }
    if( bAll || ((p->mode.spec.bRowCount==2) != ((pI->mFlg&4)!=0)) ){
      sqlite3_str_appendf(pDesc," --rowcount %s", p->mode.spec.bRowCount==2 ? "on" : "off");
    }
    zSetting = aModeStr[pI->eRSep];
    if( bAll || (zSetting && cli_strcmp(zSetting,p->mode.spec.zRowSep)!=0) ){
      sqlite3_str_appendf(pDesc, " --rowsep ");
      append_c_string(pDesc, p->mode.spec.zRowSep);
    }
    if( bAll || (pI->eCx && (p->mode.spec.nScreenWidth>0 || p->mode.bAutoScreenWidth)) ){
      if( p->mode.bAutoScreenWidth ){
        sqlite3_str_appendall(pDesc, " --sw auto");
      }else{
        sqlite3_str_appendf(pDesc," --sw %d", p->mode.spec.nScreenWidth);
      }
    }
    if( bAll || p->mode.eMode==7 ){
      sqlite3_str_appendf(pDesc," --tablename ");
      append_c_string(pDesc, p->mode.spec.zTableName);
    }
    if( bAll || p->mode.spec.bTextJsonb ){
      sqlite3_str_appendf(pDesc," --textjsonb %s", p->mode.spec.bTextJsonb==2 ? "on" : "off");
    }
    k = modeTitleDsply(p, bAll);
    if( k==1 ){
      sqlite3_str_appendall(pDesc, " --titles off");
    }else if( k==2 ){
      sqlite3_str_appendall(pDesc, " --titles on");
    }else if( k==3 ){
      sqlite3_str_appendall(pDesc, " --titles always");
    }else if( k>=4 ){
      static const char *azTitle[] = { "plain", "sql", "csv", "html", "tcl", "json"};
      sqlite3_str_appendf(pDesc, " --titles %s", azTitle[p->mode.spec.eTitle-1]);
      if( k==5 ){
        sqlite3_str_appendf(pDesc, " --titles always");
      }
    }
    if( p->mode.spec.nWidth>0 && (bAll || pI->eCx==2) ){
      int ii;
      const char *zSep = " --widths ";
      for(ii=0; ii<p->mode.spec.nWidth; ii++){
        sqlite3_str_appendf(pDesc, "%s%d", zSep, (int)p->mode.spec.aWidth[ii]);
        zSep = ",";
      }
    }else if( bAll ){
      sqlite3_str_appendall(pDesc, " --widths \"\"");
    }
    if( bAll || (pI->eCx>0 && p->mode.spec.bWordWrap) ){
      if( bAll ){
        sqlite3_str_appendf(pDesc, " --wordwrap %s", p->mode.spec.bWordWrap==2 ? "on" : "off");
      }
      if( p->mode.spec.nWrap ){
        sqlite3_str_appendf(pDesc, " --wrap %d", p->mode.spec.nWrap);
      }
      if( !bAll ) sqlite3_str_append(pDesc, " --ww", 5);
    }
    zDesc = sqlite3_str_finish(pDesc);
    cli_printf(p->out, ".mode %s\n", zDesc);
    fflush(p->out);
    sqlite3_free(zDesc);
  }
  return 0;
}

static int dotCmdOutput(ShellState *p){
  int nArg = p->dot.nArg;
  char **azArg = p->dot.azArg;
  char *zFile = 0;
  int i;
  int eMode = 0;
  int bOnce = 0;
  int bPlain = 0;
  int bKeep = 0;
  static const char *zBomUtf8 = "\357\273\277";
  const char *zBom = 0;
  char c = azArg[0][0];
  int n = strlen30(azArg[0]);
  failIfSafeMode(p, "cannot run .%s in safe mode", azArg[0]);
  if( c=='e' ){
    eMode = 'x';
    bOnce = 2;
  }else if( c=='w' ){
    eMode = 'w';
    bOnce = 2;
  }else if( n>=2 && cli_strncmp(azArg[0],"once",n)==0 ){
    bOnce = 1;
  }
  for(i=1; i<nArg; i++){
    char *z = azArg[i];
    if( z[0]=='-' ){
      if( z[1]=='-' ) z++;
      if( cli_strcmp(z,"-bom")==0 ){
        zBom = zBomUtf8;
      }else if( cli_strcmp(z,"-plain")==0 ){
        bPlain = 1;
      }else if( c=='o' && sqlite3_strglob("-[ewx]",z)==0 ){
        if( bKeep || eMode ){
          dotCmdError(p, i, "incompatible with prior options",0);
          goto dotCmdOutput_error;
        }
        eMode = z[1];
      }else if( cli_strcmp(z,"-show")==0 ){
        if( cli_output_capture ){
          fprintf(stdout, "%s", sqlite3_str_value(cli_output_capture));
        }
      }else if( cli_strcmp(z,"-keep")==0 ){
        bKeep = 1;
      }else if( optionMatch(z,"error-prefix") ){
        if( i+1>=nArg ){
          dotCmdError(p, i, "missing argument", 0);
          return 1;
        }
        free(p->zErrPrefix);
        i++;
        p->zErrPrefix = azArg[i][0]==0 ? 0 : strdup(azArg[i]);
      }else{
        dotCmdError(p, i, "unknown option", 0);
        sqlite3_free(zFile);
        return 1;
      }
    }else if( zFile==0 && eMode==0 ){
      if( bKeep ){
        dotCmdError(p, i, "incompatible with prior options",0);
        goto dotCmdOutput_error;
      }
      if( cli_strcmp(z, "memory")==0 && bOnce ){
        dotCmdError(p, 0, "cannot redirect to \"memory\"", 0);
        goto dotCmdOutput_error;
      }
      if( cli_strcmp(z, "off")==0 ){
        zFile = sqlite3_mprintf("/dev/null");
      }else{
        zFile = sqlite3_mprintf("%s", z);
      }
      if( zFile && zFile[0]=='|' ){
        while( i+1<nArg ) zFile = sqlite3_mprintf("%z %s", zFile, azArg[++i]);
        break;
      }
    }else{
      dotCmdError(p, i, "surplus argument", 0);
      sqlite3_free(zFile);
      return 1;
    }
  }
  if( zFile==0 && !bKeep ){
    zFile = sqlite3_mprintf("stdout");
    shell_check_oom(zFile);
  }
  if( bOnce ){
    p->nPopOutput = 2;
  }else{
    p->nPopOutput = 0;
  }
  if( !bKeep ) output_reset(p);
  if( eMode=='e' || eMode=='x' || eMode=='w' ){
    p->doXdgOpen = 1;
    modePush(p);
    if( eMode=='x' ){
      newTempFile(p, "csv");
      p->mode.mFlags &= ~0x01;
      p->mode.eMode = 5;
      modeSetStr(&p->mode.spec.zColumnSep, ",");
      modeSetStr(&p->mode.spec.zRowSep, "\r\n");
    }else if( eMode=='w' ){
      newTempFile(p, "html");
      if( !bPlain ) p->mode.eMode = 22;
    }else{
      newTempFile(p, "txt");
    }
    sqlite3_free(zFile);
    zFile = sqlite3_mprintf("%s", p->zTempFile);
  }
  if( !bKeep ) shell_check_oom(zFile);
  if( bKeep ){
  }else if( cli_strcmp(zFile,"memory")==0 ){
    if( cli_output_capture ){
      sqlite3_str_free(cli_output_capture);
    }
    cli_output_capture = sqlite3_str_new(0);
  }else if( zFile[0]=='|' ){
    FILE *pfPipe = popen(zFile + 1, "w");
    if( pfPipe==0 ){
      ((void) (0));
      cli_printf(stderr,"Error: cannot open pipe \"%s\"\n", zFile + 1);
      goto dotCmdOutput_error;
    }else{
      output_redir(p, pfPipe);
      if( zBom ) cli_puts(zBom, pfPipe);
      sqlite3_snprintf(sizeof(p->outfile), p->outfile, "%s", zFile);
    }
  }else{
    FILE *pfFile = output_file_open(p, zFile);
    if( pfFile==0 ){
      if( cli_strcmp(zFile,"off")!=0 ){
       ((void) (0));
       cli_printf(stderr,"Error: cannot write to \"%s\"\n", zFile);
      }
      goto dotCmdOutput_error;
    } else {
      output_redir(p, pfFile);
      if( zBom ) cli_puts(zBom, pfFile);
      if( bPlain && eMode=='w' ){
        cli_puts( "<!DOCTYPE html>\n<BODY>\n<PLAINTEXT>\n", pfFile );
      }
      sqlite3_snprintf(sizeof(p->outfile), p->outfile, "%s", zFile);
    }
  }
  sqlite3_free(zFile);
  return 0;
dotCmdOutput_error: sqlite3_free(zFile);
  return 1;
}

static int dotCmdCheck(ShellState *p){
  int nArg = p->dot.nArg;
  char **azArg = p->dot.azArg;
  int i;
  int k;
  char *zTest;
  int bKeep = 0;
  char *zCheck = 0;
  char *zPattern = 0;
  int eCheck = 0;
  int isOk;
  sqlite3_int64 iStart = p->lineno;
  if( p->zTestcase[0]==0 ){
    dotCmdError(p, 0, "no .testcase is active", 0);
    return 1;
  }
  for(i=1; i<nArg; i++){
    char *z = azArg[i];
    if( z[0]=='-' && z[1]=='-' && z[2]!=0 ) z++;
    if( cli_strcmp(z,"-keep")==0 ){
      bKeep = 1;
    }else if( cli_strcmp(z,"-show")==0 ){
      if( cli_output_capture ){
        fprintf(stdout, "%s", sqlite3_str_value(cli_output_capture));
      }
      bKeep = 1;
    }else if( z[0]=='-' && (k = pickStr(&z[1],0,"glob","notglob","exact",""))>=0 ){
      if( eCheck && eCheck!=k+1 ){
        dotCmdError(p, i, "incompatible with prior options",0);
        return 1;
      }
      eCheck = k+1;
    }else if( zCheck ){
      dotCmdError(p, i, "unknown option", 0);
      return 1;
    }else{
      zCheck = azArg[i];
    }
  }
  if( zCheck==0 ){
    dotCmdError(p, 0, "no PATTERN specified", 0);
    return 1;
  }
  if( cli_output_capture && sqlite3_str_length(cli_output_capture) ){
    zTest = sqlite3_str_value(cli_output_capture);
    shell_check_oom(zTest);
  }else{
    zTest = "";
  }
  p->nTestRun++;
  if( zCheck[0]=='<' && zCheck[1]=='<' && zCheck[2]!=0 ){
    int nCheck = strlen30(zCheck);
    sqlite3_str *pPattern = sqlite3_str_new(p->db);
    char zLine[2000];
    while( fgets(zLine,sizeof(zLine),p->in) ){
      if( strchr(zLine,'\n') ) p->lineno++;
      if( cli_strncmp(&zCheck[2],zLine,nCheck-2)==0 ) break;
      sqlite3_str_appendall(pPattern, zLine);
    }
    zPattern = sqlite3_str_finish(pPattern);
    if( zPattern==0 ){
      zPattern = sqlite3_mprintf("");
    }
  }else{
    zPattern = zCheck;
  }
  shell_check_oom(zPattern);
  switch( eCheck ){
    case 1: {
      char *zGlob = sqlite3_mprintf("*%s*", zPattern);
      isOk = testcase_glob(zGlob, zTest)!=0;
      sqlite3_free(zGlob);
      break;
    }
    case 2: {
      char *zGlob = sqlite3_mprintf("*%s*", zPattern);
      isOk = testcase_glob(zGlob, zTest)==0;
      sqlite3_free(zGlob);
      break;
    }
    case 3: {
      isOk = cli_strcmp(zTest,zPattern)==0;
      break;
    }
    default: {
      const char *z1 = zPattern;
      const char *z2 = zTest;
      size_t n1, n2;
      while( z1[0]=='\n' || z1[0]=='\r' ) z1++;
      n1 = strlen(z1);
      while( n1>0 && (z1[n1-1]=='\n' || z1[n1-1]=='\r') ) n1--;
      while( z2[0]=='\n' || z2[0]=='\r' ) z2++;
      n2 = strlen(z2);
      while( n2>0 && (z2[n2-1]=='\n' || z2[n2-1]=='\r') ) n2--;
      isOk = n1==n2 && memcmp(z1,z2,n1)==0;
      break;
    }
  }
  if( !isOk ){
    fprintf(stderr, "%s:%lld: .check failed for testcase %s\n", p->zInFile, iStart, p->zTestcase);
    p->nTestErr++;
    fprintf(stderr, "Expected: [%s]\n", zPattern);
    fprintf(stderr, "Got:      [%s]\n", zTest);
  }
  if( zPattern!=zCheck ){
    sqlite3_free(zPattern);
  }
  if( !bKeep ){
    output_reset(p);
    p->zTestcase[0] = 0;
  }
  return 0;
}

static int dotCmdTestcase(ShellState *p){
  int nArg = p->dot.nArg;
  char **azArg = p->dot.azArg;
  int i;
  const char *zName = 0;
  for(i=1; i<nArg; i++){
    char *z = azArg[i];
    if( z[0]=='-' && z[1]=='-' && z[2]!=0 ) z++;
    if( optionMatch(z,"error-prefix") ){
      if( i+1>=nArg ){
        dotCmdError(p, i, "missing argument", 0);
        return 1;
      }
      free(p->zErrPrefix);
      i++;
      p->zErrPrefix = azArg[i][0]==0 ? 0 : strdup(azArg[i]);
    }else if( zName ){
      dotCmdError(p, i, "unknown option", 0);
      return 1;
    }else{
      zName = azArg[i];
    }
  }
  output_reset(p);
  if( cli_output_capture ){
    sqlite3_str_free(cli_output_capture);
  }
  cli_output_capture = sqlite3_str_new(0);
  if( zName ){
    sqlite3_snprintf(sizeof(p->zTestcase), p->zTestcase, "%s", zName);
  }else{
    sqlite3_snprintf(sizeof(p->zTestcase), p->zTestcase, "%s:%lld", p->zInFile, p->lineno);
  }
  return 0;
}

static void parseDotRealloc(ShellState *p, int nArg){
  p->dot.nAlloc = nArg+22;
  p->dot.azArg = realloc(p->dot.azArg,p->dot.nAlloc*sizeof(char*));
