      }
      if( delim=='"' ) resolve_backslashes(p->dot.azArg[nArg]);
    }else{
      p->dot.abQuot[nArg] = 0;
      p->dot.azArg[nArg] = &z[h];
      p->dot.aiOfst[nArg] = h;
      while( z[h] && !((*__ctype_b_loc ())[(int) (((unsigned char)z[h]))] & (unsigned short int) _ISspace) ){ h++; }
