static int line_is_all_whitespace(const char *z){
  for(; *z; z++){
    if( ((*__ctype_b_loc ())[(int) (((unsigned char)z[0]))] & (unsigned short int) _ISspace) ) continue;
    if( *z=='/' && z[1]=='*' ){
      z += 2;
      while( *z && (*z!='*' || z[1]!='/') ){ z++; }
      if( *z==0 ) return 0;
      z++;
      continue;
    }
    if( *z=='-' && z[1]=='-' ){
      z += 2;
      while( *z && *z!='\n' ){ z++; }
      if( *z==0 ) return 1;
      continue;
    }
    return 0;
  }
  return 1;
}

static int line_is_command_terminator(const char *zLine){
  while( ((*__ctype_b_loc ())[(int) (((unsigned char)zLine[0]))] & (unsigned short int) _ISspace) ){ zLine++; };
  if( zLine[0]=='/' && line_is_all_whitespace(&zLine[1]) ){
    return 1;
  }
  if( (char)(__extension__ ({ int __res; if (sizeof ((unsigned char)zLine[0]) > 1) { if (__builtin_constant_p ((unsigned char)zLine[0])) { int __c = ((unsigned char)zLine[0]); __res = __c < -128 || __c > 255 ? __c : (*__ctype_tolower_loc ())[__c]; } else __res = tolower ((unsigned char)zLine[0]); } else __res = (*__ctype_tolower_loc ())[(int) ((unsigned char)zLine[0])]; __res; }))=='g' && (char)(__extension__ ({ int __res; if (sizeof ((unsigned char)zLine[1]) > 1) { if (__builtin_constant_p ((unsigned char)zLine[1])) { int __c = ((unsigned char)zLine[1]); __res = __c < -128 || __c > 255 ? __c : (*__ctype_tolower_loc ())[__c]; } else __res = tolower ((unsigned char)zLine[1]); } else __res = (*__ctype_tolower_loc ())[(int) ((unsigned char)zLine[1])]; __res; }))=='o' && line_is_all_whitespace(&zLine[2]) ){
    return 1;
  }
  return 0;
}

static int line_is_complete(char *zSql, int nSql){
  int rc;
  if( zSql==0 ) return 1;
  zSql[nSql] = ';';
  zSql[nSql+1] = 0;
  rc = sqlite3_complete(zSql);
  zSql[nSql] = 0;
  return rc;
}

static int doAutoDetectRestore(ShellState *p, const char *zSql){
  int rc = 0;
  if( p->eRestoreState<7 ){
    switch( p->eRestoreState ){
      case 0: {
        const char *zExpect = "PRAGMA foreign_keys=OFF;";
        ((void) (0));
        if( p->bSafeMode==0 && strlen(zSql)>=24 && memcmp(zSql, zExpect, 25)==0 ){
          p->eRestoreState = 1;
        }else{
          p->eRestoreState = 7;
        }
        break;
      };
      case 1: {
        int bIsDump = 0;
        const char *zExpect = "BEGIN TRANSACTION;";
        ((void) (0));
        if( memcmp(zSql, zExpect, 19)==0 ){
          const char *zQuery = "SELECT 1 FROM sqlite_schema LIMIT 1";
          sqlite3_stmt *pStmt = 0;
          bIsDump = 1;
          shellPrepare(p->db, &rc, zQuery, &pStmt);
          if( rc==0 && sqlite3_step(pStmt)==100 ){
            bIsDump = 0;
          }
          shellFinalize(&rc, pStmt);
        }
        if( bIsDump && rc==0 ){
          int bDefense = 0;
          int bDqsDdl = 0;
          sqlite3_db_config(p->db, 1010, -1, &bDefense);
          sqlite3_db_config(p->db, 1014, -1, &bDqsDdl);
          sqlite3_db_config(p->db, 1010, 0, 0);
          sqlite3_db_config(p->db, 1014, 1, 0);
          p->eRestoreState = (bDefense ? 2 : 0) + (bDqsDdl ? 4 : 0);
        }else{
          p->eRestoreState = 7;
        }
        break;
      }
      default: {
        if( sqlite3_get_autocommit(p->db) ){
          if( (p->eRestoreState & 2) ){
            sqlite3_db_config(p->db, 1010, 1, 0);
          }
          if( (p->eRestoreState & 4) ){
            sqlite3_db_config(p->db, 1014, 0, 0);
          }
          p->eRestoreState = 7;
        }
        break;
      }
    }
  }
  return rc;
}

static int runOneSqlLine( ShellState *p, char *zSql, const char *zFilename, int startline ){
  int rc;
  char *zErrMsg = 0;
  open_db(p, 0);
  if( (((p)->shellFlgs & (0x00000004))!=0) ) resolve_backslashes(zSql);
  if( p->flgProgress & 0x02 ) p->nProgress = 0;
  beginTimer(p);
  rc = shell_exec(p, zSql, &zErrMsg);
  endTimer(p);
  if( rc || zErrMsg ){
    sqlite3_str *pPrefix = sqlite3_str_new(p->db);
    const char *zErrorTail;
    const char *zErrorType;
    if( zErrMsg==0 ){
      zErrorType = "Error";
      zErrorTail = sqlite3_errmsg(p->db);
    }else if( cli_strncmp(zErrMsg, "in prepare, ",12)==0 ){
      zErrorType = "Parse error";
      zErrorTail = &zErrMsg[12];
    }else if( cli_strncmp(zErrMsg, "stepping, ", 10)==0 ){
      zErrorType = "Runtime error";
      zErrorTail = &zErrMsg[10];
    }else{
      zErrorType = "Error";
      zErrorTail = zErrMsg;
    }
    if( zFilename || !stdin_is_interactive ){
      if( cli_strcmp(zFilename,"cmdline")==0 ){
        sqlite3_str_appendf(pPrefix, "%s in %r command line argument:", zErrorType, startline);
      }else if( cli_strcmp(zFilename,"<stdin>")==0 ){
        sqlite3_str_appendf(pPrefix, "%s near line %d:", zErrorType, startline);
      }else{
        sqlite3_str_appendf(pPrefix, "%s near line %d of %s:", zErrorType, startline, zFilename);
      }
    }else{
      sqlite3_str_appendf(pPrefix, "%s:", zErrorType);
    }
    cli_printf(stderr,"%s %s\n", sqlite3_str_value(pPrefix), zErrorTail);
    sqlite3_str_free(pPrefix);
    sqlite3_free(zErrMsg);
    zErrMsg = 0;
    return 1;
  }else if( (((p)->shellFlgs & (0x00000020))!=0) ){
    cli_printf(p->out, "changes: %lld   total_changes: %lld\n", sqlite3_changes64(p->db), sqlite3_total_changes64(p->db));
  }
  if( doAutoDetectRestore(p, zSql) ) return 1;
  return 0;
}

