static char *find_xdg_file(const char *zEnvVar, const char *zSubdir, const char *zBaseName){
  char *zConfigFile = 0;
  const char *zXdgDir;
  zXdgDir = zEnvVar ? getenv(zEnvVar) : 0;
  if( zXdgDir ){
    zConfigFile = sqlite3_mprintf("%s/%s", zXdgDir, zBaseName);
  }else{
    const char * zHome = find_home_dir(0);
    if( zHome==0 ) return 0;
    zConfigFile = (zSubdir && *zSubdir) ? sqlite3_mprintf("%s/%s/%s", zHome, zSubdir, zBaseName) : sqlite3_mprintf("%s/%s", zHome, zBaseName);
  }
  shell_check_oom(zConfigFile);
  if( access(zConfigFile,0)!=0 ){
    sqlite3_free(zConfigFile);
    zConfigFile = 0;
  }
  return zConfigFile;
}

static void process_sqliterc( ShellState *p, const char *sqliterc_override ){
  char *home_dir = ((void*)0);
  char *sqliterc = (char*)sqliterc_override;
  FILE *inSaved = p->in;
  i64 savedLineno = p->lineno;
  if( sqliterc == ((void*)0) ){
    sqliterc = find_xdg_file("XDG_CONFIG_HOME", ".config", "sqlite3/sqliterc");
  }
  if( sqliterc == ((void*)0) ){
    home_dir = find_home_dir(0);
    if( home_dir==0 ){
      cli_puts("-- warning: cannot find home directory;" " cannot read ~/.sqliterc\n",stderr);
      return;
    }
    sqliterc = sqlite3_mprintf("%s/.sqliterc",home_dir);
    shell_check_oom(sqliterc);
  }
  p->in = sqliterc ? fopen(sqliterc,"rb") : 0;
  if( p->in ){
    if( stdin_is_interactive ){
      cli_printf(stderr,"-- Loading resources from %s\n", sqliterc);
    }
    if( process_input(p, sqliterc) && bail_on_error ) cli_exit(1);
    fclose(p->in);
  }else if( sqliterc_override!=0 ){
    cli_printf(stderr,"cannot open: \"%s\"\n", sqliterc);
    if( bail_on_error ) cli_exit(1);
  }
  p->in = inSaved;
  p->lineno = savedLineno;
  if( sqliterc != sqliterc_override ){
    sqlite3_free(sqliterc);
  }
}

