  if( (n==0) ) return 2;
  iPCursor = iPatch+n;
  iPEnd = iPCursor+sz;
  n = jsonbPayloadSize(pTarget, iTarget, &sz);
  if( (n==0) ) return 1;
  iTStart = iTarget+n;
  iTEndBE = iTStart+sz;
